package com.statmaker.app

import android.content.Context
import android.database.sqlite.SQLiteDatabase
import java.util.Locale

/**
 * Read-only, indexed phone view over the off-device prepared_fixture_* read model.
 *
 * Contract:
 * - no raw OddsRepository access
 * - no JSON/catalog hydration
 * - no full prepared selection-table scan
 * - every interactive read is bounded by the requested scope
 * - full prepared betting context remains in PreparedBettingSnapshotStore
 */
internal class PreparedFixtureReadModelRepository(context: Context) {
    private val databaseFile = context.applicationContext
        .getDatabasePath(DATABASE_NAME)

    data class Scope(
        val competitionIds: Set<String>,
        val dateFrom: String? = null,
        val dateTo: String? = null,
        val countries: Set<String> = emptySet(),
        val leagueCodes: Set<String> = emptySet(),
        val requestMatchKeys: Set<String> = emptySet()
    )

    data class MatchOption(
        val competitionId: String,
        val databaseMatchKey: String,
        val requestMatchKey: String,
        val localDate: String,
        val localTime: String,
        val country: String,
        val leagueCode: String,
        val competitionLabel: String,
        val homeTeam: String,
        val awayTeam: String,
        val match: OddsMatch
    ) {
        val label: String
            get() = "$competitionLabel · $homeTeam vs $awayTeam"
    }

    data class LeagueOption(
        val country: String,
        val code: String,
        val label: String
    )

    /**
     * Cheap cache identity for the prepared read model. Update All changes the SQLite file
     * timestamp/size, so UI caches can be reused between taps and invalidated on refresh
     * without another SQLite query on the main thread.
     */
    fun cacheToken(): String = "${databaseFile.lastModified()}:${databaseFile.length()}"

    fun assertInstalled() {
        openDatabase().use { db ->
            val required = setOf(
                "prepared_snapshot_meta",
                "prepared_fixture_matches",
                "prepared_fixture_markets"
            )
            val found = linkedSetOf<String>()
            db.rawQuery(
                """
                SELECT name FROM sqlite_master
                WHERE type='table'
                  AND name IN ('prepared_snapshot_meta','prepared_fixture_matches','prepared_fixture_markets')
                """.trimIndent(),
                null
            ).use { cursor ->
                while (cursor.moveToNext()) found += cursor.getString(0)
            }
            val missing = required - found
            check(missing.isEmpty()) {
                "Prepared fixture read model is not installed (${missing.joinToString()}). Run Update All."
            }
        }
    }

    fun countries(
        competitionIds: Set<String> = setOf(CompetitionBranding.DOMESTIC_ID)
    ): List<String> {
        if (CompetitionBranding.DOMESTIC_ID !in competitionIds) return emptyList()
        return openDatabase().use { db ->
            val version = latestReadyVersion(db, CompetitionBranding.DOMESTIC_ID)
                ?: return@use emptyList()
            db.rawQuery(
                """
                SELECT DISTINCT country
                FROM prepared_fixture_matches
                WHERE competition_id=? AND snapshot_version=? AND trim(country)<>''
                ORDER BY country COLLATE NOCASE
                """.trimIndent(),
                arrayOf(CompetitionBranding.DOMESTIC_ID, version)
            ).use { cursor ->
                buildList {
                    while (cursor.moveToNext()) {
                        cursor.getString(0)?.trim()?.takeIf(String::isNotBlank)?.let(::add)
                    }
                }
            }
        }
    }

    fun leagues(countries: Set<String> = emptySet()): List<LeagueOption> {
        return openDatabase().use { db ->
            val version = latestReadyVersion(db, CompetitionBranding.DOMESTIC_ID)
                ?: return@use emptyList()
            val where = mutableListOf(
                "competition_id=?",
                "snapshot_version=?",
                "trim(league_code)<>''"
            )
            val args = mutableListOf(CompetitionBranding.DOMESTIC_ID, version)
            if (countries.isNotEmpty()) {
                where += "country IN (${countries.joinToString(",") { "?" }})"
                args += countries.sorted()
            }
            db.rawQuery(
                """
                SELECT country, league_code, MIN(competition)
                FROM prepared_fixture_matches
                WHERE ${where.joinToString(" AND ")}
                GROUP BY country, league_code
                ORDER BY country COLLATE NOCASE, league_code COLLATE NOCASE
                """.trimIndent(),
                args.toTypedArray()
            ).use { cursor ->
                buildList {
                    while (cursor.moveToNext()) {
                        val country = cursor.getString(0).orEmpty()
                        val code = DomesticApiRegistry.normalizeLeagueCode(cursor.getString(1).orEmpty())
                        val rawLabel = cursor.getString(2).orEmpty()
                        if (code.isBlank()) continue
                        add(
                            LeagueOption(
                                country = country,
                                code = code,
                                label = rawLabel.ifBlank { code }
                            )
                        )
                    }
                }
            }
        }
    }


    fun dates(scope: Scope): List<String> {
        val ids = scope.competitionIds
            .filter { it in COMPETITION_IDS }
            .toSet()
            .ifEmpty { COMPETITION_IDS.toSet() }

        val values = linkedSetOf<String>()
        openDatabase().use { db ->
            ids.sorted().forEach { competitionId ->
                val version = latestReadyVersion(db, competitionId) ?: return@forEach
                val where = mutableListOf(
                    "competition_id=?",
                    "snapshot_version=?",
                    "trim(local_date)<>''"
                )
                val args = mutableListOf(competitionId, version)

                if (competitionId == CompetitionBranding.DOMESTIC_ID) {
                    if (scope.countries.isNotEmpty()) {
                        where += "country IN (${scope.countries.joinToString(",") { "?" }})"
                        args += scope.countries.sorted()
                    }
                    val normalizedLeagues = scope.leagueCodes
                        .map(DomesticApiRegistry::normalizeLeagueCode)
                        .filter(String::isNotBlank)
                        .toSet()
                    if (normalizedLeagues.isNotEmpty()) {
                        where += "league_code IN (${normalizedLeagues.joinToString(",") { "?" }})"
                        args += normalizedLeagues.sorted()
                    }
                }

                db.rawQuery(
                    """
                    SELECT DISTINCT local_date
                    FROM prepared_fixture_matches
                    WHERE ${where.joinToString(" AND ")}
                    ORDER BY local_date
                    """.trimIndent(),
                    args.toTypedArray()
                ).use { cursor ->
                    while (cursor.moveToNext()) {
                        cursor.getString(0)?.takeIf(String::isNotBlank)?.let(values::add)
                    }
                }
            }
        }

        // Required by the handoff: Date defaults to today even on a no-fixture day.
        values += bettingTodayInGreece()
        return values.sorted()
    }

    fun allMarketLabels(): List<String> {
        val available = rawMarketCanonicalLabels()
            .values
            .asSequence()
            .flatten()
            .map(::canonicalMarketFamilyLabel)
            .filterNot { it.equals("Any", true) || it.equals("All", true) }
            .distinct()
            .toCollection(linkedSetOf())

        val preferredOrder = listOf(
            "1X2",
            "Double Chance",
            "Draw No Bet",
            "Asian Handicap",
            "Winning Margin",
            "Correct Score",
            "Half-time 1X2",
            "Half-time Double Chance",
            "Asian Handicap 1H",
            "Half-time / Full-time",
            "BTTS",
            "Match Goals",
            "Asian Goals",
            "Team Goals",
            "Half-time Goals",
            "Asian Goals 1H",
            "Team Goals 1H",
            "Goals 2H",
            "Team Goals 2H",
            "Goal in Both Halves",
            "Team to Score in Both Halves",
            "Odd / Even Goals",
            "Goal Bands",
            "BTTS + Over/Under",
            "Result + Over/Under",
            "Corners",
            "Asian Corners",
            "Match Corners",
            "Team Corners",
            "Most Corners",
            "Corner Handicap",
            "Asian Corner Handicap",
            "Cards",
            "Match Cards",
            "Team Cards",
            "Yellow Cards",
            "Team Yellow Cards",
            "Red Card",
            "Shots",
            "Match Shots",
            "Team Shots",
            "Most Shots",
            "Shots on Target",
            "Match Shots on Target",
            "Team Shots on Target",
            "Most Shots on Target",
            "Fouls",
            "Match Fouls",
            "Team Fouls"
        )
        val ordered = preferredOrder.filter { it in available }
        val extras = available
            .filterNot { it in ordered }
            .sortedBy { it.lowercase(Locale.US) }
        return listOf("All") + ordered + extras
    }

    fun matchOptions(scope: Scope): List<MatchOption> =
        loadMatchRows(scope).map(::toMatchOption)

    /**
     * Small execution/UI feed for one already-selected scope.
     *
     * Only one representative selection per raw market per requested match is materialized.
     * PreparedPatternRecommendationRepository / BB then resolve the real persisted selections
     * from PreparedBettingSnapshotStore by preparedMatchKey.
     */
    fun scopedFeed(
        scope: Scope,
        requestedMarketLabels: Set<String> = emptySet(),
        fullMarketRows: Boolean = false
    ): OddsFeed {
        val rows = loadMatchRows(scope)
        if (rows.isEmpty()) return emptyFeed()
        val concreteLabels = requestedMarketLabels
            .map(::canonicalMarketFamilyLabel)
            .filterNot { it.equals("Any", true) || it.equals("All", true) }
            .toSet()
        val rawMarkets = when {
            fullMarketRows && concreteLabels.isEmpty() -> distinctRawMarkets(scope)
            concreteLabels.isEmpty() -> emptySet()
            else -> rawMarketsForCanonicalLabels(concreteLabels)
        }
        val markets = when {
            rawMarkets.isEmpty() -> emptyMap()
            fullMarketRows -> fullMarkets(rows, rawMarkets)
            else -> representativeMarkets(rows, rawMarkets)
        }
        val matches = rows.map { row ->
            row.match.copy(markets = markets[row.identity].orEmpty())
        }
        return OddsFeed(
            source = "StatMaker prepared fixture index",
            bookmaker = "Prepared exact odds",
            generatedAt = rows.map { it.snapshotVersion }.distinct().sorted().joinToString("|"),
            country = "Multiple",
            competition = "StatMaker",
            season = matches.map(OddsMatch::season).filter(String::isNotBlank).distinct().joinToString(" / "),
            matches = matches,
            leagues = emptyList()
        )
    }


    data class BettingV2Source(
        val feed: OddsFeed,
        val snapshotVersions: Map<String, String>
    )

    /** Full real fixture/quote input; never intersects prepared candidates or their old eligibility. */
    fun bettingV2Source(scope: Scope, generationId: String): BettingV2Source {
        // Update All replaces the installed database. Reject a read spanning that replacement.
        val token = cacheToken()
        return openDatabase().use { db ->
            val current = requireCurrentPreparedPatternGeneration(db, requireContent = false)
            check(current.generationId == generationId) { "PROD generation changed during source read" }
            val versions = scope.competitionIds.associateWith { latestReadyVersion(db, it).orEmpty() }
            val quotesInstalled = db.rawQuery(
                "SELECT name FROM sqlite_master WHERE type='table' " +
                    "AND name='prepared_betting_v2_quotes'", null
            ).use { it.moveToFirst() }
            check(quotesInstalled) { "Updated Betting V2 quotes are missing. Run Update All." }
            val forecastTable = DirectForecastContract.table(BuildConfig.UAT_BUILD)
            val forecastColumns = db.rawQuery("PRAGMA table_info($forecastTable)", null)
                .use { cursor -> buildSet { while (cursor.moveToNext()) add(cursor.getString(1)) } }
            check("home_scenario_probability" in forecastColumns &&
                "away_scenario_probability" in forecastColumns) {
                "Updated betting model context is missing. Run Update All."
            }
            val rows = loadMatchRows(scope)
            val rawMarkets = db.rawQuery(
                "SELECT DISTINCT market FROM prepared_betting_v2_quotes", null
            ).use { cursor -> buildSet {
                while (cursor.moveToNext()) add(cursor.getString(0))
            } }
            val markets = fullMarkets(rows, rawMarkets, bettingV2Quotes = true)
            val matches = rows.map { row -> row.match.copy(markets = markets[row.identity].orEmpty()) }
            val feed = OddsFeed(
                source = "StatMaker Betting V2 exact period quotes",
                bookmaker = "Prepared exact bookmaker odds",
                generatedAt = rows.map { it.snapshotVersion }.distinct().sorted().joinToString("|"),
                country = "Multiple", competition = "StatMaker",
                season = matches.map(OddsMatch::season).filter(String::isNotBlank).distinct().joinToString(" / "),
                matches = matches, leagues = emptyList()
            )
            check(cacheToken() == token &&
                scope.competitionIds.all { latestReadyVersion(db, it).orEmpty() == versions[it] } &&
                requireCurrentPreparedPatternGeneration(db, requireContent = false).generationId == generationId) {
                "PROD database changed during source read"
            }
            BettingV2Source(feed, versions)
        }
    }



    /**
     * Read actual model probabilities from the SAME installed PROD App-Ready SQLite
     * as the live fixture/odds catalog. No research-only JSON, separate UAT feed,
     * calibration/certificate rows, bookmaker-implied probability or legacy
     * recommendation eligibility participate in this read.
     */
    data class ProdModelEstimate(
        val win: Double,
        val push: Double,
        val runs: Int,
        val model: String,
        val metricKey: String,
        val homeHistory: Int,
        val awayHistory: Int,
        val leagueHistory: Int,
        val homeMean: Double? = null,
        val awayMean: Double? = null,
        val matchHomeWin: Double? = null,
        val matchAwayWin: Double? = null,
        val homeScenarioWin: Double? = null,
        val awayScenarioWin: Double? = null,
        val homeScenarioSample: Int = 0,
        val awayScenarioSample: Int = 0
    )

    /**
     * Opponent-strength context comes from the separately stored ELO match
     * simulation. It is calculated BEFORE considering a market's price or EV.
     * This is a matchup availability/contradiction guard, not a new model or
     * a synthetic bookmaker quote.
     */
    data class V2Matchup(
        val homeWinProbability: Double,
        val awayWinProbability: Double,
        val expectedHomeGoals: Double,
        val expectedAwayGoals: Double,
        val homeElo: Double,
        val awayElo: Double
    ) {
        fun dominantAgainst(side: MarketSelectionSide): Boolean {
            val forWin: Double
            val againstWin: Double
            val forGoals: Double
            val againstGoals: Double
            when (side) {
                MarketSelectionSide.HOME -> {
                    forWin = homeWinProbability
                    againstWin = awayWinProbability
                    forGoals = expectedHomeGoals
                    againstGoals = expectedAwayGoals
                }
                MarketSelectionSide.AWAY -> {
                    forWin = awayWinProbability
                    againstWin = homeWinProbability
                    forGoals = expectedAwayGoals
                    againstGoals = expectedHomeGoals
                }
                else -> return false
            }
            // Strong opponent dominance AND constrained attacking outlook,
            // not simply an away-team penalty or bookmaker-favorite assumption.
            return againstWin >= 0.58 && forWin <= 0.24 &&
                againstGoals >= forGoals * 1.8
        }
    }

    fun prodMatchupContexts(
        matches: List<OddsMatch>,
        snapshotVersions: Map<String, String>
    ): Map<String, V2Matchup> {
        if (matches.isEmpty()) return emptyMap()
        val token = cacheToken()
        val result = linkedMapOf<String, V2Matchup>()
        val scopes = matches.distinctBy {
            bettingCompetitionId(it) + "|" + preparedMatchKey(it)
        }.groupBy {
            bettingCompetitionId(it) to snapshotVersions[bettingCompetitionId(it)].orEmpty()
        }
        openDatabase().use { db ->
            val available = db.rawQuery(
                "SELECT name FROM sqlite_master WHERE type='table' AND name='prepared_match_simulations'",
                null
            ).use { it.moveToFirst() }
            if (!available) return emptyMap()
            scopes.forEach { (scope, fixtures) ->
                val (competition, version) = scope
                if (version.isBlank()) return@forEach
                fixtures.map(::preparedMatchKey).distinct().chunked(120).forEach { keys ->
                    val args = arrayOf(competition, version, *keys.toTypedArray())
                    db.rawQuery(
                        """
                        SELECT match_key,home_win_probability,away_win_probability,
                               expected_home_goals,expected_away_goals,
                               home_elo_rating,away_elo_rating,simulation_runs
                        FROM prepared_match_simulations
                        WHERE competition_id=? AND snapshot_version=?
                          AND match_key IN (${keys.joinToString(",") { "?" }})
                          AND simulation_model='match-monte-carlo-v2-elo'
                        """.trimIndent(), args
                    ).use { cursor ->
                        while (cursor.moveToNext()) {
                            val home = cursor.getDouble(1)
                            val away = cursor.getDouble(2)
                            val hg = cursor.getDouble(3)
                            val ag = cursor.getDouble(4)
                            val hr = cursor.getDouble(5)
                            val ar = cursor.getDouble(6)
                            if (cursor.getInt(7) < 10000 || !home.isFinite() || !away.isFinite() ||
                                !hg.isFinite() || !ag.isFinite() || !hr.isFinite() || !ar.isFinite() ||
                                home !in 0.0..1.0 || away !in 0.0..1.0 ||
                                home + away > 1.000001 || hg < 0.0 || ag < 0.0
                            ) continue
                            result["$competition|${cursor.getString(0)}"] =
                                V2Matchup(home, away, hg, ag, hr, ar)
                        }
                    }
                }
            }
        }
        check(cacheToken() == token) { "App-Ready changed during ELO matchup lookup" }
        return result
    }

    /**
     * Betting V2 reads ONLY independently fitted matchup forecasts.
     * Old prepared_simulations and Match Explorer remain untouched for
     * their own screens, not as Betting V2 probability fallbacks.
     */
    fun directBettingV2Estimates(
        offers: Map<String, PatternBackedSelection>,
        snapshotVersions: Map<String, String>
    ): Map<String, ProdModelEstimate> {
        if (offers.isEmpty()) return emptyMap()
        val forecastTable = DirectForecastContract.table(BuildConfig.UAT_BUILD)
        val token = cacheToken()
        val result = linkedMapOf<String, ProdModelEstimate>()
        val ambiguous = hashSetOf<String>()
        val scopes = offers.values.groupBy {
            bettingCompetitionId(it.match) to
                snapshotVersions[bettingCompetitionId(it.match)].orEmpty()
        }
        openDatabase().use { db ->
            val exists = db.rawQuery(
                "SELECT name FROM sqlite_master WHERE type='table' " +
                    "AND name=?", arrayOf(forecastTable)
            ).use { it.moveToFirst() }
            // No fallback to Hybrid or old Monte Carlo on missing publication.
            if (!exists) return emptyMap()
            scopes.forEach { (scope, rows) ->
                val (competition, snapshot) = scope
                if (snapshot.isBlank()) return@forEach
                rows.map(::preparedMatchKeyForSelection).distinct()
                    .chunked(140).forEach { keys ->
                        val args = arrayOf(competition, snapshot, *keys.toTypedArray())
                        db.rawQuery(
                            """
                            SELECT match_key,market,selection,team,line,odd,
                                   win_probability,push_probability,actual_runs,
                                   prediction_model,metric_key,home_history_sample,
                                   away_history_sample,league_training_sample,
                                   prediction_home_mean,prediction_away_mean,
                                   match_home_win_probability,match_away_win_probability,
                                   home_scenario_probability,away_scenario_probability,
                                   home_scenario_sample,away_scenario_sample
                            FROM $forecastTable
                            WHERE competition_id=? AND snapshot_version=?
                              AND match_key IN (${keys.joinToString(",") { "?" }})
                            """.trimIndent(), args
                        ).use { cursor ->
                            while (cursor.moveToNext()) {
                                if (cursor.isNull(5) || cursor.isNull(6) ||
                                    cursor.isNull(7)) continue
                                val key = listOf(
                                    competition,
                                    cursor.getString(0).orEmpty(),
                                    cursor.getString(1).orEmpty().trim(),
                                    cursor.getString(2).orEmpty().trim(),
                                    if (cursor.isNull(3)) "" else cursor.getString(3).trim(),
                                    if (cursor.isNull(4)) ""
                                        else cursor.getDouble(4).toBits().toString()
                                ).joinToString("\u0001")
                                val matching = offers[key] ?: continue
                                if (key in ambiguous ||
                                    matching.odd.toBits() != cursor.getDouble(5).toBits()) continue
                                val win = cursor.getDouble(6)
                                val push = cursor.getDouble(7)
                                val runs = cursor.getInt(8)
                                val model = cursor.getString(9).orEmpty()
                                if (win !in 0.0..1.0 || push !in 0.0..1.0 ||
                                    win + push > 1.000001 ||
                                    !DirectForecastContract.accepts(model, runs, BuildConfig.UAT_BUILD)) continue
                                val estimate = ProdModelEstimate(
                                    win, push, runs, model,
                                    cursor.getString(10).orEmpty(),
                                    cursor.getInt(11).coerceAtLeast(0),
                                    cursor.getInt(12).coerceAtLeast(0),
                                    cursor.getInt(13).coerceAtLeast(0),
                                    cursor.getDouble(14), cursor.getDouble(15),
                                    cursor.getDouble(16), cursor.getDouble(17),
                                    if (cursor.isNull(18)) null else cursor.getDouble(18),
                                    if (cursor.isNull(19)) null else cursor.getDouble(19),
                                    cursor.getInt(20), cursor.getInt(21)
                                )
                                val previous = result[key]
                                if (previous != null && previous != estimate) {
                                    result.remove(key)
                                    ambiguous.add(key)
                                } else if (previous == null) {
                                    result[key] = estimate
                                }
                            }
                        }
                    }
            }
        }
        check(cacheToken() == token) { "App-Ready changed while reading direct V2 forecasts" }
        return result
    }

    private fun preparedMatchKeyForSelection(selection: PatternBackedSelection): String =
        preparedMatchKey(selection.match)

    /**
     * Exact full-time 1/X/2 bookmaker prices for displayed V2 suggestions.
     *
     * Read only the SAME installed App-Ready snapshot and fixture identity;
     * this is presentation-only, never a source for model probability, EV or
     * STRONG eligibility. No inferred/implied or fabricated bookmaker odds.
     */
    fun displayedOneXTwoOdds(
        matches: List<OddsMatch>,
        snapshotVersions: Map<String, String>,
        bettingV2Quotes: Boolean = false
    ): Map<String, List<OddsSelection>> {
        if (matches.isEmpty()) return emptyMap()
        val versionToken = cacheToken()
        val byScope = matches.distinctBy {
            bettingCompetitionId(it) + "|" + preparedMatchKey(it)
        }.groupBy { match ->
            bettingCompetitionId(match) to snapshotVersions[bettingCompetitionId(match)].orEmpty()
        }
        val complete = linkedMapOf<String, List<OddsSelection>>()
        val partial = linkedMapOf<String, List<OddsSelection>>()
        openDatabase().use { db ->
            val names = db.rawQuery("SELECT name FROM sqlite_master WHERE type='table'", null)
                .use { cursor -> buildSet {
                    while (cursor.moveToNext()) add(cursor.getString(0))
                } }
            byScope.forEach { (scope, fixtures) ->
                val (competition, snapshot) = scope
                if (snapshot.isBlank()) return@forEach
                val matchByKey = fixtures.associateBy(::preparedMatchKey)
                matchByKey.keys.chunked(120).forEach { keys ->
                    val args = arrayOf(competition, snapshot, *keys.toTypedArray())
                    val placeholders = keys.joinToString(",") { "?" }
                    fun absorb(sourceRows: Map<String, List<OddsSelection>>, preferComplete: Boolean) {
                        sourceRows.forEach sourceRow@{ (id, rows) ->
                            val fixture = matchByKey[id.removePrefix("$competition|")] ?: return@sourceRow
                            // Only full-time 1X2, only positive actual source prices.
                            val bySide = rows.groupBy { quote ->
                                normalizedMarketIdentity(quote, fixture)?.takeIf {
                                    it.subMarketKey == "RESULT_1X2"
                                }?.selectionSide
                            }
                            val required = listOf(
                                MarketSelectionSide.HOME,
                                MarketSelectionSide.DRAW,
                                MarketSelectionSide.AWAY
                            )
                            val picked = required.mapNotNull { side ->
                                val values = bySide[side].orEmpty()
                                    .filter { it.odd.isFinite() && it.odd > 1.0 }
                                // Different prices for the same side in a single
                                // unattributed source are ambiguous: never choose
                                // the most favourable or invent a consensus.
                                values.singleOrNull()?.takeIf {
                                    values.map { v -> v.odd.toBits() }.distinct().size == 1
                                } ?: values.firstOrNull()?.takeIf {
                                    values.map { v -> v.odd.toBits() }.distinct().size == 1
                                }
                            }
                            if (picked.size == 3) {
                                if (preferComplete || id !in complete) complete[id] = picked
                            } else if (picked.isNotEmpty() && id !in complete &&
                                picked.size > partial[id].orEmpty().size) {
                                partial[id] = picked
                            }
                        }
                    }
                    val quoteTable = if (bettingV2Quotes) "prepared_betting_v2_quotes"
                        else "prepared_fixture_markets"
                    if (quoteTable in names) {
                        val rows = linkedMapOf<String, MutableList<OddsSelection>>()
                        db.rawQuery(
                            """
                            SELECT match_key,market,selection,team,line,odd
                            FROM $quoteTable
                            WHERE competition_id=? AND snapshot_version=?
                              AND match_key IN ($placeholders)
                            """.trimIndent(), args
                        ).use { cursor ->
                            while (cursor.moveToNext()) {
                                if (cursor.isNull(5)) continue
                                val id = "$competition|${cursor.getString(0)}"
                                rows.getOrPut(id) { mutableListOf() }.add(
                                    OddsSelection(
                                        market = cursor.getString(1).orEmpty(),
                                        selection = cursor.getString(2).orEmpty(),
                                        team = if (cursor.isNull(3)) null else cursor.getString(3),
                                        line = if (cursor.isNull(4)) null else cursor.getDouble(4),
                                        odd = cursor.getDouble(5)
                                    )
                                )
                            }
                        }
                        absorb(rows, preferComplete = true)
                    }
                    // Some existing PROD bundles carry additional canonical
                    // result quotes in prepared_selections. The identity-side
                    // columns are the published model's actual bookmaker mapping,
                    // not a guess from fixture strength or a market probability.
                    if (!bettingV2Quotes && "prepared_selections" in names) {
                        val rows = linkedMapOf<String, MutableList<OddsSelection>>()
                        db.rawQuery(
                            """
                            SELECT match_key,identity_selection_side,selection_odd,
                                   selection_market,selection_name,selection_team
                            FROM prepared_selections
                            WHERE competition_id=? AND snapshot_version=?
                              AND match_key IN ($placeholders)
                              AND identity_sub_market_key='RESULT_1X2'
                            """.trimIndent(), args
                        ).use { cursor ->
                            while (cursor.moveToNext()) {
                                if (cursor.isNull(2)) continue
                                val label = when (cursor.getString(1).orEmpty()) {
                                    "HOME" -> "Home"
                                    "DRAW" -> "Draw"
                                    "AWAY" -> "Away"
                                    else -> continue
                                }
                                val id = "$competition|${cursor.getString(0)}"
                                rows.getOrPut(id) { mutableListOf() }.add(
                                    OddsSelection(
                                        market = "1X2",
                                        selection = label,
                                        team = if (cursor.isNull(5)) null else cursor.getString(5),
                                        line = null,
                                        odd = cursor.getDouble(2)
                                    )
                                )
                            }
                        }
                        absorb(rows, preferComplete = false)
                    }
                }
            }
        }
        check(cacheToken() == versionToken) {
            "App-Ready changed during real full-time 1X2 quote lookup"
        }
        val combined = partial.toMutableMap().apply { putAll(complete) }
        // The installed source can genuinely be missing 1 or X. That is
        // visible as unavailable, never reconstructed from 2 or simulation EV.
        return combined
    }

    /**
     * Pattern execution boundary.
     *
     * UI/filtering may expose the complete fixture universe, but Find Bets must only hand the
     * prepared recommendation layer fixtures that:
     * 1) have at least one prepared recommendation candidate for the current request, and
     * 2) have a full prepared_match row for the active snapshot.
     *
     * This keeps schedule-only/non-prepared fixtures out of loadPreparedMatchFeed while preserving
     * the full persisted match/context boundary used by the local UAT recommendation repository.
     */
    fun patternExecutionFeed(
        scope: Scope,
        request: PatternBetsRequest,
        requestedMarketLabels: Set<String> = emptySet()
    ): OddsFeed {
        val rows = loadMatchRows(scope)
        if (rows.isEmpty()) return emptyFeed()

        val candidateKeys = patternCandidateMatchKeys(request)
        if (candidateKeys.isEmpty()) return emptyFeed()

        val preparedKeys = preparedMatchKeys(scope)
        if (preparedKeys.isEmpty()) return emptyFeed()

        val executionRows = rows.filter { row ->
            row.match.key in candidateKeys &&
                row.databaseMatchKey in preparedKeys[row.competitionId].orEmpty()
        }
        if (executionRows.isEmpty()) return emptyFeed()

        val concreteLabels = requestedMarketLabels
            .map(::canonicalMarketFamilyLabel)
            .filterNot { it.equals("Any", true) || it.equals("All", true) }
            .toSet()

        // PB candidates already identify the exact prepared selections. Market rows are only
        // materialized when the user explicitly narrows the market scope.
        val rawMarkets = if (concreteLabels.isEmpty()) {
            emptySet()
        } else {
            rawMarketsForCanonicalLabels(concreteLabels)
        }
        val markets = if (rawMarkets.isEmpty()) {
            emptyMap()
        } else {
            representativeMarkets(executionRows, rawMarkets)
        }
        val matches = executionRows.map { row ->
            row.match.copy(markets = markets[row.identity].orEmpty())
        }

        return OddsFeed(
            source = "StatMaker prepared candidate/full-match execution scope",
            bookmaker = "Prepared exact odds",
            generatedAt = executionRows
                .map { it.snapshotVersion }
                .distinct()
                .sorted()
                .joinToString("|"),
            country = "Multiple",
            competition = "StatMaker",
            season = matches.map(OddsMatch::season)
                .filter(String::isNotBlank)
                .distinct()
                .joinToString(" / "),
            matches = matches,
            leagues = emptyList()
        )
    }

    private fun patternCandidateMatchKeys(
        request: PatternBetsRequest
    ): Set<String> {
        return openDatabase().use { db ->
            val generationId = db.rawQuery(
                """
                SELECT generation_id
                FROM prepared_pattern_generation
                WHERE state='ready'
                ORDER BY built_at_ms DESC
                LIMIT 1
                """.trimIndent(),
                null
            ).use { cursor ->
                if (cursor.moveToFirst()) cursor.getString(0).orEmpty() else ""
            }
            if (generationId.isBlank()) return@use emptySet()

            val where = mutableListOf(
                "generation_id=?",
                "recommendation_eligible=1",
                "selection_odd>=?"
            )
            val args = mutableListOf(
                generationId,
                request.minSelectionOdd.toString()
            )

            val competitions = request.competitionFilters
                .filter(String::isNotBlank)
                .toSet()
            if (competitions.isNotEmpty()) {
                where += "competition_id IN (${competitions.joinToString(",") { "?" }})"
                args += competitions.sorted()
            }

            val dates = preparedPatternRequestDates(request)
            if (dates.isNotEmpty()) {
                where += "local_date IN (${dates.joinToString(",") { "?" }})"
                args += dates.sorted()
            }

            val explicitMarkets = request.marketFilters
                .ifEmpty { setOf(request.marketFilter) }
                .map(::canonicalMarketFamilyLabel)
                .filterNot {
                    it.equals("Any", true) || it.equals("All", true)
                }
                .toSet()
            if (explicitMarkets.isNotEmpty()) {
                where += "market_family IN (${explicitMarkets.joinToString(",") { "?" }})"
                args += explicitMarkets.sorted()
            }

            val valueTier = request.valueTrendFilter.tier?.name
            if (valueTier != null) {
                where += "value_tier=?"
                args += valueTier
            } else if (request.valueOnly) {
                where += "value_tier IS NOT NULL"
            }

            db.rawQuery(
                """
                SELECT DISTINCT match_key
                FROM prepared_pattern_candidates
                WHERE ${where.joinToString(" AND ")}
                """.trimIndent(),
                args.toTypedArray()
            ).use { cursor ->
                buildSet {
                    while (cursor.moveToNext()) {
                        cursor.getString(0)
                            ?.takeIf(String::isNotBlank)
                            ?.let(::add)
                    }
                }
            }
        }
    }

    private fun preparedMatchKeys(
        scope: Scope
    ): Map<String, Set<String>> {
        val ids = scope.competitionIds
            .filter { it in COMPETITION_IDS }
            .toSet()
            .ifEmpty { setOf(CompetitionBranding.DOMESTIC_ID) }

        return openDatabase().use { db ->
            buildMap {
                ids.sorted().forEach { competitionId ->
                    val version = latestReadyVersion(db, competitionId) ?: return@forEach
                    val where = mutableListOf(
                        "competition_id=?",
                        "snapshot_version=?"
                    )
                    val args = mutableListOf(competitionId, version)

                    scope.dateFrom?.takeIf(String::isNotBlank)?.let {
                        where += "local_date>=?"
                        args += it
                    }
                    scope.dateTo?.takeIf(String::isNotBlank)?.let {
                        where += "local_date<=?"
                        args += it
                    }

                    val keys = db.rawQuery(
                        """
                        SELECT match_key
                        FROM prepared_matches
                        WHERE ${where.joinToString(" AND ")}
                        """.trimIndent(),
                        args.toTypedArray()
                    ).use { cursor ->
                        buildSet {
                            while (cursor.moveToNext()) {
                                cursor.getString(0)
                                    ?.takeIf(String::isNotBlank)
                                    ?.let(::add)
                            }
                        }
                    }
                    put(competitionId, keys)
                }
            }
        }
    }

    fun marketLabels(scope: Scope): List<String> {
        val rawMarkets = distinctRawMarkets(scope)
        if (rawMarkets.isEmpty()) return emptyList()
        val families = rawMarketCanonicalLabels()
        return rawMarkets.asSequence()
            .flatMap { raw -> families[raw].orEmpty().asSequence() }
            .map(::canonicalMarketFamilyLabel)
            .filterNot { it.equals("All", true) || it.equals("Any", true) }
            .distinct()
            .sortedBy { it.lowercase(Locale.US) }
            .toList()
    }

    fun scheduleMatches(
        localDate: String,
        sourceId: String? = null,
        country: String? = null,
        leagueCode: String? = null
    ): List<MatchOption> {
        val ids = sourceId?.let(::setOf) ?: COMPETITION_IDS.toSet()
        return matchOptions(
            Scope(
                competitionIds = ids,
                dateFrom = localDate,
                dateTo = localDate,
                countries = country?.takeIf(String::isNotBlank)?.let(::setOf).orEmpty(),
                leagueCodes = leagueCode?.takeIf(String::isNotBlank)?.let(::setOf).orEmpty()
            )
        )
    }

    private data class StoredRow(
        val competitionId: String,
        val snapshotVersion: String,
        val databaseMatchKey: String,
        val localDate: String,
        val match: OddsMatch
    ) {
        val identity: String
            get() = "$competitionId\u0001$snapshotVersion\u0001$databaseMatchKey"
    }

    private fun loadMatchRows(scope: Scope): List<StoredRow> {
        val ids = scope.competitionIds
            .filter { it in COMPETITION_IDS }
            .toSet()
            .ifEmpty { setOf(CompetitionBranding.DOMESTIC_ID) }

        return openDatabase().use { db ->
            buildList {
                ids.sorted().forEach { competitionId ->
                    val version = latestReadyVersion(db, competitionId) ?: return@forEach
                    val where = mutableListOf(
                        "competition_id=?",
                        "snapshot_version=?"
                    )
                    val args = mutableListOf(competitionId, version)
                    scope.dateFrom?.takeIf(String::isNotBlank)?.let {
                        where += "local_date>=?"
                        args += it
                    }
                    scope.dateTo?.takeIf(String::isNotBlank)?.let {
                        where += "local_date<=?"
                        args += it
                    }
                    if (competitionId == CompetitionBranding.DOMESTIC_ID) {
                        if (scope.countries.isNotEmpty()) {
                            where += "country IN (${scope.countries.joinToString(",") { "?" }})"
                            args += scope.countries.sorted()
                        }
                        if (scope.leagueCodes.isNotEmpty()) {
                            val normalized = scope.leagueCodes
                                .map(DomesticApiRegistry::normalizeLeagueCode)
                                .filter(String::isNotBlank)
                                .toSet()
                            if (normalized.isNotEmpty()) {
                                where += "league_code IN (${normalized.joinToString(",") { "?" }})"
                                args += normalized.sorted()
                            }
                        }
                    }

                    db.rawQuery(
                        """
                        SELECT match_key, local_date, id, date, kickoff, league_code, country,
                               competition, season, provider_home_team, provider_away_team,
                               home_team, away_team, canonical_home_team, canonical_away_team,
                               home_team_logo, away_team_logo, team_mapping_status,
                               usable_for_stats, venue
                        FROM prepared_fixture_matches
                        WHERE ${where.joinToString(" AND ")}
                        ORDER BY local_date, kickoff, country, league_code, home_team, away_team
                        """.trimIndent(),
                        args.toTypedArray()
                    ).use { cursor ->
                        while (cursor.moveToNext()) {
                            val dbKey = cursor.getString(0).orEmpty()
                            val localDate = cursor.getString(1).orEmpty()
                            val sourceLabel = CompetitionBranding.forId(competitionId).label
                            val domestic = competitionId == CompetitionBranding.DOMESTIC_ID
                            val match = OddsMatch(
                                id = cursor.getString(2).orEmpty(),
                                date = cursor.getString(3).orEmpty(),
                                kickoff = cursor.getString(4).orEmpty(),
                                leagueCode = if (domestic) {
                                    cursor.getString(5).orEmpty()
                                } else {
                                    competitionId
                                },
                                country = if (domestic) {
                                    cursor.getString(6).orEmpty()
                                } else {
                                    "UEFA"
                                },
                                competition = if (domestic) {
                                    cursor.getString(7).orEmpty()
                                } else {
                                    sourceLabel
                                },
                                season = cursor.getString(8).orEmpty(),
                                providerHomeTeam = cursor.getString(9).orEmpty(),
                                providerAwayTeam = cursor.getString(10).orEmpty(),
                                homeTeam = cursor.getString(11).orEmpty(),
                                awayTeam = cursor.getString(12).orEmpty(),
                                canonicalHomeTeam = if (cursor.isNull(13)) null else cursor.getString(13),
                                canonicalAwayTeam = if (cursor.isNull(14)) null else cursor.getString(14),
                                homeTeamLogo = if (cursor.isNull(15)) null else cursor.getString(15),
                                awayTeamLogo = if (cursor.isNull(16)) null else cursor.getString(16),
                                teamMappingStatus = cursor.getString(17).orEmpty().ifBlank { "matched" },
                                usableForStats = cursor.getInt(18) == 1,
                                markets = emptyList(),
                                venue = if (cursor.isNull(19)) null else cursor.getString(19),
                                squadContext = null
                            )
                            val requestKey = match.key
                            if (scope.requestMatchKeys.isNotEmpty() &&
                                requestKey !in scope.requestMatchKeys
                            ) continue
                            add(
                                StoredRow(
                                    competitionId = competitionId,
                                    snapshotVersion = version,
                                    databaseMatchKey = dbKey,
                                    localDate = localDate,
                                    match = match
                                )
                            )
                        }
                    }
                }
            }
        }
    }


    private fun fullMarkets(
        rows: List<StoredRow>,
        rawMarkets: Set<String>,
        bettingV2Quotes: Boolean = false
    ): Map<String, List<OddsSelection>> {
        if (rows.isEmpty() || rawMarkets.isEmpty()) return emptyMap()
        val quoteTable = if (bettingV2Quotes) "prepared_betting_v2_quotes"
            else "prepared_fixture_markets"
        return openDatabase().use { db ->
            buildMap<String, MutableList<OddsSelection>> {
                rows.groupBy { it.competitionId to it.snapshotVersion }
                    .forEach { (scope, scopedRows) ->
                        val (competitionId, version) = scope
                        scopedRows.chunked(300).forEach { chunk ->
                            val keys = chunk.map(StoredRow::databaseMatchKey).toSet()
                            if (keys.isEmpty()) return@forEach
                            val keyPlaceholders = keys.joinToString(",") { "?" }
                            val marketPlaceholders = rawMarkets.joinToString(",") { "?" }
                            val args = mutableListOf(competitionId, version).apply {
                                addAll(keys.sorted())
                                addAll(rawMarkets.sorted())
                            }
                            val identityByDbKey = chunk.associate {
                                it.databaseMatchKey to it.identity
                            }
                            db.rawQuery(
                                """
                                SELECT match_key, market, selection, team, line, odd
                                FROM $quoteTable
                                WHERE competition_id=? AND snapshot_version=?
                                  AND match_key IN ($keyPlaceholders)
                                  AND market IN ($marketPlaceholders)
                                ORDER BY match_key, ordinal
                                """.trimIndent(),
                                args.toTypedArray()
                            ).use { cursor ->
                                while (cursor.moveToNext()) {
                                    val identity = identityByDbKey[cursor.getString(0)] ?: continue
                                    getOrPut(identity) { mutableListOf() }.add(
                                        OddsSelection(
                                            market = cursor.getString(1).orEmpty(),
                                            selection = cursor.getString(2).orEmpty(),
                                            team = if (cursor.isNull(3)) null else cursor.getString(3),
                                            line = if (cursor.isNull(4)) null else cursor.getDouble(4),
                                            odd = cursor.getDouble(5)
                                        )
                                    )
                                }
                            }
                        }
                    }
            }.mapValues { (_, value) -> value.toList() }
        }
    }

    private fun representativeMarkets(
        rows: List<StoredRow>,
        rawMarkets: Set<String>
    ): Map<String, List<OddsSelection>> {
        if (rows.isEmpty()) return emptyMap()
        return openDatabase().use { db ->
            buildMap<String, MutableList<OddsSelection>> {
                rows.groupBy { it.competitionId to it.snapshotVersion }
                    .forEach { (scope, scopedRows) ->
                        val (competitionId, version) = scope
                        scopedRows.chunked(400).forEach { chunk ->
                            val keys = chunk.map(StoredRow::databaseMatchKey).toSet()
                            if (keys.isEmpty()) return@forEach
                            val placeholders = keys.joinToString(",") { "?" }
                            val args = mutableListOf(competitionId, version).apply {
                                addAll(keys.sorted())
                            }
                            db.rawQuery(
                                """
                                SELECT match_key, market,
                                       MIN(selection), MIN(team), MIN(line), MIN(odd)
                                FROM prepared_fixture_markets
                                WHERE competition_id=? AND snapshot_version=?
                                  AND match_key IN ($placeholders)
                                  AND market IN (${rawMarkets.joinToString(",") { "?" }})
                                GROUP BY match_key, market
                                ORDER BY match_key, market
                                """.trimIndent(),
                                (args + rawMarkets.sorted()).toTypedArray()
                            ).use { cursor ->
                                val identityByDbKey = chunk.associate {
                                    it.databaseMatchKey to it.identity
                                }
                                while (cursor.moveToNext()) {
                                    val identity = identityByDbKey[cursor.getString(0)] ?: continue
                                    getOrPut(identity) { mutableListOf() }.add(
                                        OddsSelection(
                                            market = cursor.getString(1).orEmpty(),
                                            selection = cursor.getString(2).orEmpty(),
                                            team = if (cursor.isNull(3)) null else cursor.getString(3),
                                            line = if (cursor.isNull(4)) null else cursor.getDouble(4),
                                            odd = if (cursor.isNull(5)) 2.0 else cursor.getDouble(5)
                                        )
                                    )
                                }
                            }
                        }
                    }
            }.mapValues { (_, value) -> value.toList() }
        }
    }


    private fun distinctRawMarkets(scope: Scope): Set<String> {
        val rows = loadMatchRows(scope)
        if (rows.isEmpty()) return emptySet()
        return openDatabase().use { db ->
            buildSet {
                rows.groupBy { it.competitionId to it.snapshotVersion }
                    .forEach { (versionScope, scopedRows) ->
                        val (competitionId, version) = versionScope
                        scopedRows.chunked(400).forEach { chunk ->
                            val keys = chunk.map(StoredRow::databaseMatchKey).toSet()
                            if (keys.isEmpty()) return@forEach
                            val args = mutableListOf(competitionId, version).apply {
                                addAll(keys.sorted())
                            }
                            db.rawQuery(
                                """
                                SELECT DISTINCT market
                                FROM prepared_fixture_markets
                                WHERE competition_id=? AND snapshot_version=?
                                  AND match_key IN (${keys.joinToString(",") { "?" }})
                                ORDER BY market
                                """.trimIndent(),
                                args.toTypedArray()
                            ).use { cursor ->
                                while (cursor.moveToNext()) {
                                    cursor.getString(0)?.takeIf(String::isNotBlank)?.let(::add)
                                }
                            }
                        }
                    }
            }
        }
    }

    private fun rawMarketsForCanonicalLabels(labels: Set<String>): Set<String> {
        if (labels.isEmpty()) return emptySet()
        return rawMarketCanonicalLabels()
            .filterValues { canonicalLabels ->
                canonicalLabels.any { canonicalMarketFamilyLabel(it) in labels }
            }
            .keys
    }

    /**
     * Derives raw->canonical market aliases from the app's existing market identity code.
     * There is no duplicated market-family switch here. Only one real bookmaker row is read for
     * each distinct raw market name (32 in the current published bundle).
     */
    private fun rawMarketCanonicalLabels(): Map<String, Set<String>> {
        synchronized(marketMapLock) {
            rawMarketCanonicalCache?.let { return it }
        }

        val built = openDatabase().use { db ->
            val samples = db.rawQuery(
                """
                SELECT fm.market, fm.selection, fm.team, fm.line, fm.odd,
                       m.id, m.date, m.kickoff, m.league_code, m.country, m.competition,
                       m.season, m.provider_home_team, m.provider_away_team,
                       m.home_team, m.away_team, m.canonical_home_team, m.canonical_away_team,
                       m.home_team_logo, m.away_team_logo, m.team_mapping_status,
                       m.usable_for_stats, m.venue, m.competition_id
                FROM prepared_fixture_markets fm
                JOIN prepared_fixture_matches m
                  ON m.competition_id=fm.competition_id
                 AND m.snapshot_version=fm.snapshot_version
                 AND m.match_key=fm.match_key
                WHERE fm.rowid IN (
                    SELECT MIN(rowid)
                    FROM prepared_fixture_markets
                    GROUP BY market
                )
                ORDER BY fm.market
                """.trimIndent(),
                null
            ).use { cursor ->
                buildList {
                    while (cursor.moveToNext()) {
                        val rawMarket = cursor.getString(0).orEmpty()
                        val selection = OddsSelection(
                            market = rawMarket,
                            selection = cursor.getString(1).orEmpty(),
                            team = if (cursor.isNull(2)) null else cursor.getString(2),
                            line = if (cursor.isNull(3)) null else cursor.getDouble(3),
                            odd = cursor.getDouble(4)
                        )
                        val competitionId = cursor.getString(23).orEmpty()
                        val domestic = competitionId == CompetitionBranding.DOMESTIC_ID
                        val match = OddsMatch(
                            id = cursor.getString(5).orEmpty(),
                            date = cursor.getString(6).orEmpty(),
                            kickoff = cursor.getString(7).orEmpty(),
                            leagueCode = if (domestic) cursor.getString(8).orEmpty() else competitionId,
                            country = if (domestic) cursor.getString(9).orEmpty() else "UEFA",
                            competition = if (domestic) cursor.getString(10).orEmpty()
                                else CompetitionBranding.forId(competitionId).label,
                            season = cursor.getString(11).orEmpty(),
                            providerHomeTeam = cursor.getString(12).orEmpty(),
                            providerAwayTeam = cursor.getString(13).orEmpty(),
                            homeTeam = cursor.getString(14).orEmpty(),
                            awayTeam = cursor.getString(15).orEmpty(),
                            canonicalHomeTeam = if (cursor.isNull(16)) null else cursor.getString(16),
                            canonicalAwayTeam = if (cursor.isNull(17)) null else cursor.getString(17),
                            homeTeamLogo = if (cursor.isNull(18)) null else cursor.getString(18),
                            awayTeamLogo = if (cursor.isNull(19)) null else cursor.getString(19),
                            teamMappingStatus = cursor.getString(20).orEmpty().ifBlank { "matched" },
                            usableForStats = cursor.getInt(21) == 1,
                            markets = listOf(selection),
                            venue = if (cursor.isNull(22)) null else cursor.getString(22),
                            squadContext = null
                        )
                        add(rawMarket to match)
                    }
                }
            }

            samples.associate { (rawMarket, match) ->
                val labels = exactOddsMarketLabels(
                    OddsFeed(
                        source = "Prepared market identity sample",
                        bookmaker = "Prepared exact odds",
                        generatedAt = "",
                        country = match.country,
                        competition = match.competition,
                        season = match.season,
                        matches = listOf(match),
                        leagues = emptyList()
                    )
                )
                    .filterNot { it.equals("All", true) || it.equals("Any", true) }
                    .toSet()
                rawMarket to labels
            }
        }

        synchronized(marketMapLock) {
            rawMarketCanonicalCache = built
        }
        return built
    }

    private fun toMatchOption(row: StoredRow): MatchOption {
        val match = row.match
        val label = if (row.competitionId == CompetitionBranding.DOMESTIC_ID) {
            match.competition.ifBlank { match.leagueCode }
        } else {
            CompetitionBranding.forId(row.competitionId).label
        }
        return MatchOption(
            competitionId = row.competitionId,
            databaseMatchKey = row.databaseMatchKey,
            requestMatchKey = match.key,
            localDate = row.localDate,
            localTime = bettingLocalTime(match).ifBlank { "--:--" },
            country = match.country,
            leagueCode = DomesticApiRegistry.normalizeLeagueCode(
                match.leagueCode.ifBlank { match.competition }
            ),
            competitionLabel = label,
            homeTeam = match.homeTeam,
            awayTeam = match.awayTeam,
            match = match
        )
    }

    private fun latestReadyVersion(db: SQLiteDatabase, competitionId: String): String? =
        db.rawQuery(
            """
            SELECT snapshot_version
            FROM prepared_snapshot_meta
            WHERE competition_id=? AND lower(state)='ready'
            ORDER BY built_at_ms DESC
            LIMIT 1
            """.trimIndent(),
            arrayOf(competitionId)
        ).use { cursor ->
            if (cursor.moveToFirst()) cursor.getString(0)?.takeIf(String::isNotBlank) else null
        }

    private fun openDatabase(): SQLiteDatabase {
        check(databaseFile.isFile && databaseFile.length() > 4096L) {
            "Prepared betting database is missing. Run Update All."
        }
        return SQLiteDatabase.openDatabase(
            databaseFile.absolutePath,
            null,
            SQLiteDatabase.OPEN_READONLY
        )
    }

    private fun emptyFeed(): OddsFeed = OddsFeed(
        source = "StatMaker prepared fixture index",
        bookmaker = "Prepared exact odds",
        generatedAt = "",
        country = "Multiple",
        competition = "StatMaker",
        season = "",
        matches = emptyList(),
        leagues = emptyList()
    )

    companion object {
        private const val DATABASE_NAME = "statmaker_prepared_betting.db"
        private val COMPETITION_IDS = listOf(
            CompetitionBranding.DOMESTIC_ID,
            CompetitionBranding.CHAMPIONS_ID,
            CompetitionBranding.EUROPA_ID,
            CompetitionBranding.CONFERENCE_ID
        )
        private val marketMapLock = Any()
        @Volatile private var rawMarketCanonicalCache: Map<String, Set<String>>? = null
    }
}

package com.statmaker.app

import android.util.Log

internal class PreparedPatternRecommendationsUnavailableException(message: String) :
    IllegalStateException(message)

/**
 * Phone-side final recommendation read-model.
 *
 * This class never invokes PatternBetsEngine. It performs indexed reads, resolves the already
 * persisted selection rows, applies request predicates and renders the persisted proposal order.
 */
internal class PreparedPatternRecommendationRepository(
    private val snapshotStore: PreparedBettingSnapshotStore,
    private val confidenceSnapshot: () -> ModelPerformanceConfidenceSnapshot = { ModelPerformanceConfidenceSnapshot.EMPTY },
    private val fullMarketSource: PreparedFixtureReadModelRepository? =
        if (BuildConfig.UAT_BUILD) snapshotStore.fixtureReadModel else null,
    private val log: (String) -> Unit = { message -> Log.d(PERF_TAG, message) }
) {
    private data class HybridCacheKey(
        val generationId: String,
        val performanceRevision: Long,
        val request: PatternBetsRequest,
        val requestLabel: String,
        val forcedScopeId: String?
    )

    private data class HybridCacheEntry(
        val createdAtMs: Long,
        val result: PatternBetsToolRunResult
    )

    private val hybridCacheLock = Any()
    private val hybridResultCache = linkedMapOf<HybridCacheKey, HybridCacheEntry>()
    private var hybridCacheGenerationId: String? = null

    private fun cachedProbabilityFirstUat(
        oddsFeed: OddsFeed,
        request: PatternBetsRequest,
        requestLabel: String,
        forcedScopeId: String?
    ): PatternBetsToolRunResult {
        val generation = requireCurrentGeneration()
        val key = HybridCacheKey(
            generationId = generation.generationId,
            performanceRevision = ModelPerformanceConfidenceRefreshState.currentRevision(),
            request = request,
            requestLabel = requestLabel,
            forcedScopeId = forcedScopeId
        )
        val now = System.currentTimeMillis()
        synchronized(hybridCacheLock) {
            if (hybridCacheGenerationId != generation.generationId) {
                hybridResultCache.clear()
                hybridCacheGenerationId = generation.generationId
            }
            hybridResultCache[key]
                ?.takeIf { now - it.createdAtMs <= HYBRID_RESULT_CACHE_TTL_MS }
                ?.let { entry ->
                    log(
                        "hybrid cache-hit age=${now - entry.createdAtMs}ms " +
                            "generation=${generation.generationId.take(12)}"
                    )
                    return entry.result
                }
            hybridResultCache.remove(key)
        }

        val result = queryProbabilityFirstUat(
            oddsFeed = oddsFeed,
            request = request,
            requestLabel = requestLabel,
            forcedScopeId = forcedScopeId,
            generation = generation
        )
        synchronized(hybridCacheLock) {
            if (hybridCacheGenerationId == generation.generationId) {
                hybridResultCache[key] = HybridCacheEntry(System.currentTimeMillis(), result)
                while (hybridResultCache.size > MAX_HYBRID_RESULT_CACHE_ENTRIES) {
                    hybridResultCache.entries.firstOrNull()?.key?.let(hybridResultCache::remove)
                }
            }
        }
        return result
    }

    fun query(
        oddsFeed: OddsFeed,
        request: PatternBetsRequest,
        requestLabel: String,
        forcedScopeId: String? = null
    ): PatternBetsToolRunResult {
        // Betting V2 is the ONLY UAT recommendation path. No Solid, legacy
        // candidate ranking, historical posterior, or old Hybrid fallback.
        // PROD stays unchanged until the user explicitly approves promotion.
        if (BuildConfig.UAT_BUILD) {
            return queryBettingV2Uat(oddsFeed, request, requestLabel)
        }
        val probabilityFirstActive = HybridUatRanking.isActive(request)
        val probabilityFirstAll =
            request.valueTrendFilter == BettingValueTrendFilterMode.ALL_TRENDS &&
                !request.suggestionType.equals("Paroli", ignoreCase = true)

        if (probabilityFirstAll) {
            val strongRun = cachedProbabilityFirstUat(
                oddsFeed = oddsFeed,
                request = request.copy(
                    valueOnly = true,
                    valueTrendFilter = BettingValueTrendFilterMode.STRONG_VALUE
                ),
                requestLabel = requestLabel,
                forcedScopeId = forcedScopeId
            )
            // User-facing All deliberately means Strong + Solid. Marginal/No-signal are
            // diagnostic candidates only and never re-enter the recommendation surface.
            val solidRun = queryPreparedDefault(
                oddsFeed = oddsFeed,
                request = request.copy(
                    valueOnly = false,
                    valueTrendFilter = BettingValueTrendFilterMode.SOLID_VALUE
                ),
                requestLabel = requestLabel,
                forcedScopeId = forcedScopeId
            )
            return mergeProbabilityFirstStrongIntoAll(strongRun, solidRun)
        }

        if (probabilityFirstActive) {
            val requestedConfidence = request.valueTrendFilter.confidenceTier
            val baseRequest = if (requestedConfidence == null) {
                request
            } else {
                request.copy(valueTrendFilter = BettingValueTrendFilterMode.STRONG_VALUE)
            }
            val strongRun = cachedProbabilityFirstUat(
                oddsFeed = oddsFeed,
                request = baseRequest,
                requestLabel = requestLabel,
                forcedScopeId = forcedScopeId
            )
            return if (requestedConfidence == null) {
                strongRun
            } else {
                filterCachedStrongByConfidence(strongRun, requestedConfidence)
            }
        }
        return queryPreparedDefault(
            oddsFeed = oddsFeed,
            request = request,
            requestLabel = requestLabel,
            forcedScopeId = forcedScopeId
        )
    }

    /**
     * V2 UAT adapter. Existing DB rows are used as a read-only fixture/odds catalog,
     * NEVER as evidence that a market is suitable for a Strong recommendation.
     *
     * Until actual, validated V2 matchup forecasts are available,
     * fail closed and show an informative empty state. Do not fall back to Hybrid.
     */
    private fun queryBettingV2Uat(
        oddsFeed: OddsFeed,
        request: PatternBetsRequest,
        requestLabel: String
    ): PatternBetsToolRunResult {
        val started = System.nanoTime()
        val now = System.currentTimeMillis()
        val generation = requireCurrentPreparedPatternGeneration(
            snapshotStore.readableDatabase, requireContent = false
        )
        val competitions = request.competitionFilters.ifEmpty { PREPARED_PATTERN_COMPETITIONS.toSet() }
        val source = requireNotNull(fullMarketSource) { "Full PROD fixture read model is unavailable" }
            .bettingV2Source(
                PreparedFixtureReadModelRepository.Scope(competitionIds = competitions),
                generation.generationId
            )
        // Request predicates are preserved. The full markets on each fixture remain attached for
        // the existing header's 1/X/2 prices and the unchanged analysis/simulation controls.
        // Scope preserves every genuine fixture; provider identity is
        // evaluated separately by the V2-only recommendation gate below.
        // Geography and domestic league codes scope national competitions.
        // UEFA is selected by its own competition control, as in the unified
        // source runner; e.g. a Europe/country-derived league list must not
        // silently eliminate explicitly selected CL/EL/Conference fixtures.
        val scopedIds = source.feed.matches.groupBy(::bettingCompetitionId)
            .flatMap { (competition, fixtures) ->
                val scopedRequest = if (competition == CompetitionBranding.DOMESTIC_ID) {
                    request.copy(competitionFilters = setOf(competition))
                } else {
                    request.copy(
                        competitionFilters = setOf(competition),
                        continentFilter = null, countryFilter = null,
                        leagueFilter = null, leagueFilters = emptySet()
                    )
                }
                scopePatternOddsFeed(
                    source.feed.copy(matches = fixtures, leagues = emptyList()), scopedRequest
                ).matches
            }.mapTo(hashSetOf()) {
                "${bettingCompetitionId(it)}|${preparedMatchKey(it)}"
            }
        val scopedMatches = source.feed.matches.filter {
            "${bettingCompetitionId(it)}|${preparedMatchKey(it)}" in scopedIds
        }
        val rows = scopedMatches.flatMap { match ->
            match.markets.map { quote ->
                PatternBackedSelection(
                    match = match, oddsSelection = quote,
                    category = canonicalMarketFamilyLabel(quote.market),
                    patternSupport = "", hitRate = 0.0, sample = 0, reasoning = ""
                )
            }
        }
        val byIdentity = rows.groupBy(::bettingV2ExactSelectionId)
        val diagnostics = linkedMapOf<String, Int>()
        fun reject(reason: String, count: Int = 1) {
            diagnostics[reason] = (diagnostics[reason] ?: 0) + count
        }
        val indexed = linkedMapOf<String, PatternBackedSelection>()
        byIdentity.forEach { (id, quotes) ->
            // Distinct prices for one un-attributed source quote are ambiguous, not a best-odds pick.
            if (quotes.map { it.odd.toBits() }.distinct().size != 1) {
                reject("AMBIGUOUS_QUOTE", quotes.size)
                return@forEach
            }
            val row = quotes.first()
            when {
                row.match.id.isBlank() ||
                    (!row.match.usableForStats && !(
                        row.match.teamMappingStatus == "provider_identity" &&
                        bettingCompetitionId(row.match) != CompetitionBranding.DOMESTIC_ID
                    )) -> reject("UNVERIFIED_FIXTURE_IDENTITY")
                RetiredBettingMarketPolicy.isRetiredRawMarket(row.oddsSelection.market) ->
                    reject("UNSUPPORTED_MARKET")
                !requestedBettingMarketAllows(row, request) || row.odd < request.minSelectionOdd ||
                    PersistentMarketExclusions.excludes(row) -> reject("REQUEST_FILTER")
                !ModelSettlementContract.isRecommendationSettleable(row) ->
                    reject("UNSUPPORTED_SETTLEMENT")
                else -> indexed[id] = row
            }
        }
        // Only direct, newly fitted V2 matchup forecasts. No legacy
        // prepared_simulations, Hybrid or certification-layer fallback.
        val estimates = requireNotNull(fullMarketSource).directBettingV2Estimates(
            indexed, source.snapshotVersions
        )
        data class Candidate(
            val row: PatternBackedSelection,
            val estimate: PreparedFixtureReadModelRepository.ProdModelEstimate,
            val ev: Double,
            val tier: BettingEngineV2.Tier,
            val family: MarketBroadGroup,
            val favouriteAssessment: BettingFavouritePolicy.Assessment
        )
        val eligible = indexed.mapNotNull { (id, row) ->
            val estimate = estimates[id] ?: run {
                reject("NO_DIRECT_V2_FORECAST")
                return@mapNotNull null
            }
            val identity = normalizedMarketIdentity(row)
            val odd = row.odd
            val p = estimate.win
            val push = estimate.push
            val kickoff = bettingLocalKickoff(row.match).epochMillis ?: 0L
            val ev = p * odd + push - 1.0
            when {
                identity == null -> {
                    reject("UNRESOLVED_MARKET_IDENTITY")
                    null
                }
                !odd.isFinite() || odd <= BettingEngineV2.MIN_ODD_EXCLUSIVE ||
                    odd >= BettingEngineV2.MAX_ODD_EXCLUSIVE -> {
                    reject("ODDS_OUTSIDE_V2_RANGE")
                    null
                }
                kickoff <= now -> {
                    reject("ALREADY_STARTED")
                    null
                }
                p < BettingEngineV2.MIN_CONSERVATIVE_WIN || !ev.isFinite() || ev <= 0.0 -> {
                    reject("LOW_MODEL_PROBABILITY_OR_EV")
                    null
                }
                else -> {
                    val assessment = BettingFavouritePolicy.assess(row.match, identity, estimate)
                    if (assessment.rejection != null) {
                        reject(assessment.rejection)
                        return@mapNotNull null
                    }
                    Candidate(
                    row = row,
                    estimate = estimate,
                    ev = ev,
                    tier = when {
                        assessment.confidenceProbability >= 0.80 -> BettingEngineV2.Tier.HIGH
                        assessment.confidenceProbability >= 0.70 -> BettingEngineV2.Tier.CONFIRMED
                        else -> BettingEngineV2.Tier.DEVELOPING
                    },
                    family = identity.broadGroup,
                    favouriteAssessment = assessment
                )
                }
            }
        }
        // One opinion per fixture and broad market family across match totals,
        // both teams, periods, directions and lines. Exact quote identity still
        // joins the unchanged forecast and settlement; it is not the opinion key.
        val familyGroups = eligible.groupBy { candidate ->
            val row = candidate.row
            listOf(
                bettingCompetitionId(row.match), preparedMatchKey(row.match),
                candidate.family.name
            ).joinToString("\u0001")
        }
        val duplicateOpinions = eligible.size - familyGroups.size
        if (duplicateOpinions > 0) reject("SAME_FIXTURE_MARKET_FAMILY", duplicateOpinions)
        val selected = familyGroups.values.map { alternatives ->
            alternatives.sortedWith(
                Comparator<Candidate> { left, right ->
                    BettingFavouritePolicy.compare(left.favouriteAssessment, right.favouriteAssessment)
                }.thenByDescending { it.estimate.win }
                    .thenByDescending { it.ev }
                    .thenBy { bettingV2ExactSelectionId(it.row) }
            ).first()
        }.filter { candidate ->
            when (request.valueTrendFilter) {
                BettingValueTrendFilterMode.SOLID_VALUE,
                BettingValueTrendFilterMode.MARGINAL_VALUE -> false
                BettingValueTrendFilterMode.STRONG_HIGH ->
                    candidate.tier == BettingEngineV2.Tier.HIGH
                BettingValueTrendFilterMode.STRONG_CONFIRMED ->
                    candidate.tier == BettingEngineV2.Tier.CONFIRMED
                BettingValueTrendFilterMode.STRONG_DEVELOPING ->
                    candidate.tier == BettingEngineV2.Tier.DEVELOPING
                else -> true
            }
        }.sortedWith(
            // One newly fitted model supplies every supported market.
            // No family quotas, hardcoded favourite preferences or old scores.
            compareBy<Candidate> { it.tier.ordinal }
                .thenByDescending { it.favouriteAssessment.confidenceProbability }
                .thenByDescending { it.estimate.win }
                .thenByDescending { it.ev }
                .thenBy { bettingV2ExactSelectionId(it.row) }
        )
        // Restore the full pre-existing "Στοιχεία και Ανάλυση" evidence.
        // Historical hit series, team splits, form/trend and bookmaker evidence
        // are DISPLAY-ONLY: they never approve or reject a V2 pick.
        val displayEvidence = linkedMapOf<String, PatternBackedSelection>()
        selected.map { it.row }.groupBy { bettingCompetitionId(it.match) }
            .forEach { (competition, issued) ->
                val snapshot = source.snapshotVersions[competition] ?: return@forEach
                val matchKeys = issued.mapTo(linkedSetOf(), ::preparedMatchKeyForV2Display)
                matchKeys.chunked(200).forEach chunkLoop@{ chunk ->
                    val preparedFeed = snapshotStore.loadPreparedMatchFeed(
                        competition, snapshot, chunk.toSet()
                    ) ?: return@chunkLoop
                    snapshotStore.loadForFeed(
                        competition, snapshot, preparedFeed, PreparedSelectionPurpose.ALL
                    )?.selections.orEmpty().forEach { row ->
                        displayEvidence[bettingV2ExactSelectionId(row)] = row
                    }
                }
            }
        // The 1/X/2 mini row is display-only, but must be restored even
        // when the recommended market itself is Over, Corners, DNB, etc.
        val fullTimeQuotes = requireNotNull(fullMarketSource).displayedOneXTwoOdds(
            selected.map { it.row.match }, source.snapshotVersions, bettingV2Quotes = true
        )
        val selections = selected.map { candidate ->
            val raw = candidate.row
            val scopedMatchKey = bettingCompetitionId(raw.match) + "|" +
                preparedMatchKey(raw.match)
            val quoteTriplet = fullTimeQuotes[scopedMatchKey].orEmpty()
            val visibleMatch = if (quoteTriplet.isEmpty()) raw.match else raw.match.copy(
                markets = raw.match.markets.filterNot {
                    normalizedMarketIdentity(it, raw.match)?.subMarketKey == "RESULT_1X2"
                } + quoteTriplet
            )
            val archived = displayEvidence[bettingV2ExactSelectionId(raw)]
                ?.takeIf { it.odd.toBits() == raw.odd.toBits() }
            (archived?.copy(match = visibleMatch, oddsSelection = raw.oddsSelection)
                ?: raw.copy(match = visibleMatch)).copy(
                reasoning = "V2 independent matchup fit · " + candidate.estimate.model +
                    " · " + DirectForecastContract.description(candidate.estimate.model, candidate.estimate.runs) +
                    " · Expected ${candidate.estimate.metricKey}: " +
                    String.format(java.util.Locale.US, "%.2f / %.2f",
                        candidate.estimate.homeMean, candidate.estimate.awayMean) +
                    " · Actual team history: ${candidate.estimate.homeHistory} / ${candidate.estimate.awayHistory}" +
                    candidate.favouriteAssessment.supportProbability?.let { support ->
                        " · Favourite scenario support: " +
                            String.format(java.util.Locale.US, "%.1f%%", support * 100.0)
                    }.orEmpty()
            )
        }
        val chosenById = selected.associateBy { bettingV2ExactSelectionId(it.row) }
        val confidence = selections.associate { row ->
            preparedSelectionKey(row) to when (
                chosenById.getValue(bettingV2ExactSelectionId(row)).tier
            ) {
                BettingEngineV2.Tier.HIGH -> ModelPerformanceConfidenceTier.HIGH_CONFIDENCE
                BettingEngineV2.Tier.CONFIRMED -> ModelPerformanceConfidenceTier.CONFIRMED
                BettingEngineV2.Tier.DEVELOPING -> ModelPerformanceConfidenceTier.DEVELOPING
            }
        }
        val scores = selections.associate { row ->
            val value = chosenById.getValue(bettingV2ExactSelectionId(row))
            val win = value.estimate.win
            val push = value.estimate.push
            val decisive = if (push < 1.0) win / (1.0 - push) else win
            val market = (1.0 / row.odd).coerceIn(0.0, 1.0)
            preparedSelectionKey(row) to HybridUatRanking.Score(
                probability = decisive,
                marketProbability = market,
                edge = decisive - market,
                expectedValue = value.ev,
                legacySupport = 0.0,
                // No calibrated reliability exists; don't invent one.
                reliability = 0.0,
                hitRate = 0.0,
                modelBacked = true,
                marketPreferred = false,
                longshotPenalty = 0.0,
                safetyPassed = true,
                rankingScore = win,
                odd = row.odd,
                conservativeProbability = win,
                conservativeExpectedValue = value.ev,
                conservativeEdge = decisive - market,
                predictionSource = if (value.estimate.model == DirectForecastContract.EXACT_MODEL)
                    "BETTING_V4_EXACT_CALIBRATED_ESTIMATE" else "BETTING_V2_PROD_SIMULATION_ESTIMATE",
                winProbability = win,
                conservativeWinProbability = win,
                pushProbability = push,
                conservativePushProbability = push,
                simulationProbability = win,
                simulationRuns = value.estimate.runs,
                historySampleFloor = minOf(value.estimate.homeHistory, value.estimate.awayHistory)
            )
        }
        val suggestions = if (request.suggestionType == "Paroli") emptyList() else
            selections.map { row ->
                PatternBetSuggestion(
                    match = row.match, possibleBet = row, selections = listOf(row),
                    estimatedOdds = row.odd, rawProductOdds = row.odd,
                    correlationLevel = "Single", averageHitRate = 0.0
                )
            }
        if (request.suggestionType != "Single Bet") reject("JOINT_PAROLI_MODEL_UNAVAILABLE")
        log(
            "betting-v2-real-prod generation=${generation.generationId} " +
                "requestedCompetitions=$competitions " +
                "requestedContinent=${request.continentFilter} " +
                "requestedCountry=${request.countryFilter} " +
                "requestedLeagues=${request.leagueFilters} " +
                "sourceFixtures=${source.feed.matches.groupingBy(::bettingCompetitionId).eachCount()} " +
                "fixtures=${scopedMatches.size} rawQuotes=${rows.size} " +
                "directV2Models=${estimates.size} " +
                "directV2Candidates=${eligible.size} strong=${suggestions.size} " +
                "strongCompetitions=${selected.groupingBy { bettingCompetitionId(it.row.match) }.eachCount()} " +
                "calibration=not_required rejected=$diagnostics"
        )
        val result = PatternBetsToolResult(
            selections, emptyList(), suggestions, null, emptyList(), emptyList()
        )
        return PatternBetsToolRunResult(
            allSelections = rows,
            singleSelections = selections,
            paroliSelections = emptyList(),
            suggestions = suggestions,
            paroli = null,
            earlySignals = emptyList(),
            result = result,
            sourceMs = (System.nanoTime() - started) / 1_000_000,
            requestLabel = requestLabel,
            paritySnapshots = emptyList(),
            sharedEvidenceBySelectionKey = emptyMap(),
            trendCoverage = PatternTrendCoverageReport(rows.size, 0, 0, 0, emptyList()),
            probabilityFirstStrongSelectionKeys =
                selections.mapTo(linkedSetOf(), ::preparedSelectionKey),
            hybridConfidenceBySelectionKey = confidence,
            fixtureScoresBySelectionKey = scores
        )
    }

    private fun preparedMatchKeyForV2Display(row: PatternBackedSelection): String =
        preparedMatchKey(row.match)

    private fun queryPreparedDefault(
        oddsFeed: OddsFeed,
        request: PatternBetsRequest,
        requestLabel: String,
        forcedScopeId: String?
    ): PatternBetsToolRunResult {
        val startedAt = System.nanoTime()
        val generation = requireCurrentGeneration()
        val candidatesStartedAt = System.nanoTime()
        val persistedCandidates = loadCandidates(generation.generationId, request)
        val candidatesMs = elapsedMilliseconds(candidatesStartedAt)

        val selectionsStartedAt = System.nanoTime()
        val selectionsByReference = loadPreparedSelections(persistedCandidates)
        val resolvedFeed = preparedFeedForSelections(selectionsByReference.values)
        val scopedFeed = scopePatternOddsFeed(resolvedFeed, request)
        val scopedPreparedMatchKeys = scopedFeed.matches
            .mapTo(linkedSetOf(), ::preparedMatchKey)
        val scopedRows = persistedCandidates.filter { candidate ->
            val selection = selectionsByReference[candidate.referenceKey] ?: return@filter false
            preparedMatchKey(selection.match) in scopedPreparedMatchKeys &&
                candidate.allowsScope(request) &&
                requestedBettingMarketAllows(selection, request) &&
                !PersistentMarketExclusions.excludes(selection)
        }
        val allSelections = scopedRows.mapNotNull { selectionsByReference[it.referenceKey] }
        val rowBySelectionKey = scopedRows.associateBy { candidate -> candidate.selectionKey }
        val selectionByReference = allSelections.associateBy { selection ->
            val competitionId = bettingCompetitionId(selection.match)
            preparedPatternSelectionReference(competitionId, preparedSelectionKey(selection))
        }
        val selectionsMs = elapsedMilliseconds(selectionsStartedAt)

        val eligibleRows = scopedRows.filter { candidate ->
            val selection = selectionByReference[candidate.referenceKey] ?: return@filter false
            val resultPolicyEligible =
                !ResultMarketPolicy.requiresFixtureResultModel(selection) ||
                    candidate.policyPremiumEligible
            candidate.recommendationEligible &&
                resultPolicyEligible &&
                !RetiredBettingMarketPolicy.isRetiredRawMarket(selection.oddsSelection.market) &&
                candidate.allowsRequest(request) &&
                normalizedMarketIdentity(selection) != null &&
                isSaneExactOdd(selection) &&
                (!request.halfLineOnly || isHalfLineOrNonLine(selection))
        }
        val valueFilteredSelections = eligibleRows.mapNotNull { selectionByReference[it.referenceKey] }
        val scoreBySelectionKey = rowBySelectionKey.mapValues { it.value.selectionScore }
        val singleQualityParoliReferences = preparedParoliSingleQualityReferences(
            rows = eligibleRows,
            selectionsByReference = selectionByReference,
            pool = valueFilteredSelections,
            scoreBySelectionKey = scoreBySelectionKey
        )
        val policyEligibleRows = eligibleRows.filter(PreparedPatternCandidate::policyPremiumEligible)
        val policyRows = policyEligibleRows.filter { candidate ->
            candidate.referenceKey in singleQualityParoliReferences
        }
        val paroliSelections = policyRows.mapNotNull { selectionByReference[it.referenceKey] }
        val evidenceBySelectionKey = allSelections.mapNotNull { selection ->
            PreparedBettingEvidenceRegistry.lookup(selection)?.let { evidence ->
                PatternTrendCoverageAudit.selectionKey(selection) to SharedBettingEvidence(
                    bookmaker = evidence,
                    trend = null
                )
            }
        }.toMap()

        val wantsSingles = !request.suggestionType.equals("Paroli", ignoreCase = true)
        val wantsParoli = !request.suggestionType.equals("Single Bet", ignoreCase = true)
        val singlesStartedAt = System.nanoTime()
        val generatedSuggestions = if (wantsSingles) {
            preparedSingles(
                rows = eligibleRows,
                selectionsByReference = selectionByReference,
                request = request
            )
        } else {
            emptyList()
        }
        val alternativesBySelectionKey = if (wantsSingles) {
            generatedSuggestions.associate { suggestion ->
                val current = suggestion.possibleBet
                alternativeSelectionKey(current) to preparedSingleAlternatives(
                    current = current,
                    pool = valueFilteredSelections,
                    scoreBySelectionKey = scoreBySelectionKey
                )
            }
        } else {
            emptyMap()
        }
        val suggestions = if (wantsSingles) {
            BettingValueFirstRanking.stableRank(
                items = generatedSuggestions,
                selections = { suggestion ->
                    listOf(suggestion.possibleBet) +
                        alternativesBySelectionKey[alternativeSelectionKey(suggestion.possibleBet)].orEmpty()
                },
                evidenceBySelectionKey = evidenceBySelectionKey
            )
        } else {
            emptyList()
        }
        val singlesMs = elapsedMilliseconds(singlesStartedAt)

        val paroliStartedAt = System.nanoTime()
        val scopeId = forcedScopeId ?: preparedPatternScopeId(request)
        val parolis = if (wantsParoli) {
            val selector = PreparedPatternParoliSelector(
                candidateByReference = policyRows.associateBy(PreparedPatternCandidate::referenceKey)
            )
            val generated = selector.findParolis(
                selections = paroliSelections,
                request = request,
                maxResults = MAX_PAROLI_GENERATION_POOL
            )
            val promotedPrimary = generated.firstOrNull()?.let { first ->
                promotePrimaryValueLegs(
                    initial = first,
                    selector = selector,
                    selections = paroliSelections,
                    request = request,
                    evidenceBySelectionKey = evidenceBySelectionKey
                )
            }
            (listOfNotNull(promotedPrimary) + generated.drop(1))
                .distinctBy { suggestion ->
                    suggestion.selections.joinToString("||") { selection ->
                        preparedPatternSelectionReference(
                            bettingCompetitionId(selection.match),
                            preparedSelectionKey(selection)
                        )
                    }
                }
                .take(MAX_VISIBLE_PAROLIS)
        } else {
            emptyList()
        }
        val paroliMs = elapsedMilliseconds(paroliStartedAt)
        val paroli = parolis.firstOrNull()
        val result = PatternBetsToolResult(
            selections = valueFilteredSelections,
            paroliSelections = paroliSelections,
            suggestions = suggestions,
            paroli = paroli,
            earlySignals = emptyList(),
            parolis = parolis
        )
        val elapsedMs = elapsedMilliseconds(startedAt)
        val visibleSingles = suggestions.map { suggestion ->
            BettingParityResult(suggestion.selections.ifEmpty { listOf(suggestion.possibleBet) }, suggestion.estimatedOdds)
        }
        val visibleParoli = parolis.map { suggestion ->
            BettingParityResult(suggestion.selections, suggestion.totalOdds)
        }
        val parity = listOf(
            bettingParitySnapshot("Pattern", requestLabel, valueFilteredSelections, visibleSingles + visibleParoli, elapsedMs),
            bettingParitySnapshot("Singles", requestLabel, valueFilteredSelections, visibleSingles, elapsedMs),
            bettingParitySnapshot("Paroli", requestLabel, valueFilteredSelections, visibleParoli, elapsedMs)
        )
        val diagnostics = PatternParoliEligibilityDiagnostics(
            evaluatedCandidates = valueFilteredSelections.size,
            premiumEligibleSelections = policyEligibleRows.size,
            distinctPremiumMatches = policyEligibleRows.map { it.matchKey }.distinct().size,
            requestedLegs = request.paroliLegCount.coerceAtLeast(2),
            generatedParolis = parolis.size,
            minSelectionOdd = request.minSelectionOdd,
            targetOddsPreference = request.paroliTargetOddsPreference,
            rejectedByReason = eligibleRows.mapNotNull { it.policyRejectionReason }
                .groupingBy { it }.eachCount()
        )
        log(
            "query=${elapsedMs}ms generation=${generation.generationId.take(12)} scope=$scopeId " +
                "candidates=${persistedCandidates.size} resolved=${selectionsByReference.size} " +
                "scopedMatches=${scopedPreparedMatchKeys.size} scopedRows=${scopedRows.size} " +
                "candidatesMs=$candidatesMs selectionsMs=$selectionsMs singlesMs=$singlesMs " +
                "paroliMs=$paroliMs source=${allSelections.size} singles=${suggestions.size} parolis=${parolis.size}"
        )
        return PatternBetsToolRunResult(
            allSelections = allSelections,
            singleSelections = valueFilteredSelections,
            paroliSelections = paroliSelections,
            suggestions = suggestions,
            paroli = paroli,
            earlySignals = emptyList(),
            result = result,
            sourceMs = selectionsMs,
            requestLabel = requestLabel,
            paritySnapshots = parity,
            sharedEvidenceBySelectionKey = evidenceBySelectionKey,
            trendCoverage = PatternTrendCoverageReport(
                totalSelections = allSelections.size,
                mappedSelections = 0,
                evidenceSelections = 0,
                completeLast5Selections = 0,
                rows = emptyList()
            ),
            alternativePoolIndex = BettingAlternativePoolIndex.EMPTY,
            singleAlternativesBySelectionKey = alternativesBySelectionKey,
            emptyMessage = null,
            paroliDiagnostics = diagnostics,
            parolis = parolis
        )
    }

    private fun mergeProbabilityFirstStrongIntoAll(
        strongRun: PatternBetsToolRunResult,
        allRun: PatternBetsToolRunResult
    ): PatternBetsToolRunResult {
        fun selectionKey(selection: PatternBackedSelection): String =
            preparedPatternSelectionReference(
                bettingCompetitionId(selection.match),
                preparedSelectionKey(selection)
            )

        val strongOpinionKeys = strongRun.suggestions
            .mapTo(linkedSetOf()) { HybridUatRanking.opinionKey(it.possibleBet) }

        // "All" is a true superset of the probability-first Strong product.
        // A Strong opinion owns only its exact target, not every other market in the match.
        val mergedSuggestions = (
            strongRun.suggestions +
                allRun.suggestions.filter { suggestion ->
                    HybridUatRanking.opinionKey(suggestion.possibleBet) !in strongOpinionKeys
                }
            ).distinctBy { suggestion -> selectionKey(suggestion.possibleBet) }

        val mergedSingles = (strongRun.singleSelections + allRun.singleSelections)
            .distinctBy(::selectionKey)
        val mergedAllSelections = (strongRun.allSelections + allRun.allSelections)
            .distinctBy(::selectionKey)
        val mergedEvidence = allRun.sharedEvidenceBySelectionKey +
            strongRun.sharedEvidenceBySelectionKey

        return allRun.copy(
            allSelections = mergedAllSelections,
            singleSelections = mergedSingles,
            suggestions = mergedSuggestions,
            result = allRun.result.copy(
                selections = mergedSingles,
                suggestions = mergedSuggestions
            ),
            sourceMs = allRun.sourceMs + strongRun.sourceMs,
            sharedEvidenceBySelectionKey = mergedEvidence,
            emptyMessage = if (mergedSuggestions.isNotEmpty()) null else allRun.emptyMessage,
            probabilityFirstStrongSelectionKeys =
                strongRun.probabilityFirstStrongSelectionKeys,
            hybridConfidenceBySelectionKey =
                strongRun.hybridConfidenceBySelectionKey,
            fixtureScoresBySelectionKey = strongRun.fixtureScoresBySelectionKey
        )
    }

    private fun promotePrimaryValueLegs(
        initial: PatternParoliSuggestion,
        selector: PreparedPatternParoliSelector,
        selections: List<PatternBackedSelection>,
        request: PatternBetsRequest,
        evidenceBySelectionKey: Map<String, SharedBettingEvidence>
    ): PatternParoliSuggestion {
        val valueSelections = selections.filter { selection ->
            BettingValueFirstRanking.hasSignal(selection, evidenceBySelectionKey)
        }
        if (valueSelections.isEmpty()) return initial

        var current = initial
        for (legIndex in current.selections.indices) {
            val currentLeg = current.selections.getOrNull(legIndex) ?: continue
            if (BettingValueFirstRanking.hasSignal(currentLeg, evidenceBySelectionKey)) continue

            val alternatives = selector.paroliLegAlternativeSelections(
                current = current,
                legIndex = legIndex,
                selections = valueSelections,
                request = request,
                direction = 1,
                minimumHitRate = StrictBetRules.MIN_HIT_RATE,
                minimumOdd = request.minSelectionOdd
            )
            val replacement = BettingValueFirstRanking.bestValueSelection(
                selections = alternatives,
                evidenceBySelectionKey = evidenceBySelectionKey
            ) ?: continue
            val updated = selector.replaceParoliLegWithSelection(
                current = current,
                legIndex = legIndex,
                replacement = replacement,
                request = request,
                minimumHitRate = StrictBetRules.MIN_HIT_RATE,
                minimumOdd = request.minSelectionOdd
            )
            if (updated != null) current = updated
        }
        return current
    }

    private fun requireCurrentGeneration(): PreparedPatternGeneration {
        return runCatching {
            requireCurrentPreparedPatternGeneration(snapshotStore.readableDatabase)
        }.getOrElse { error ->
            throw unavailable(error.message ?: "final recommendation generation is invalid")
        }
    }

    private fun loadCandidates(
        generationId: String,
        request: PatternBetsRequest,
        strongQualityOnly: Boolean = false,
        hybridStrongFloorOnly: Boolean = false
    ): List<PreparedPatternCandidate> {
        val competitions = request.competitionFilters.filter(String::isNotBlank).toSet()
        val dates = preparedPatternRequestDates(request)
        val where = mutableListOf("generation_id=?")
        val args = mutableListOf(generationId)
        if (competitions.isNotEmpty()) {
            where += "competition_id IN (${competitions.joinToString(",") { "?" }})"
            args += competitions.sorted()
        }
        if (dates.isNotEmpty()) {
            where += "local_date IN (${dates.joinToString(",") { "?" }})"
            args += dates.sorted()
        }
        request.continentFilter?.takeIf(String::isNotBlank)?.let { continent ->
            where += "continent=?"
            args += continent
        }
        request.countryFilter?.takeIf(String::isNotBlank)?.let { country ->
            where += "country=?"
            args += country
        }
        val leagues = request.leagueFilters.filter(String::isNotBlank).toSet()
            .ifEmpty { request.leagueFilter?.takeIf(String::isNotBlank)?.let(::setOf).orEmpty() }
        if (leagues.isNotEmpty()) {
            where += "league_code IN (${leagues.joinToString(",") { "?" }})"
            args += leagues.sorted()
        }
        val matchKeys = request.matchKeyFilters.filter(String::isNotBlank).toSet()
            .ifEmpty { request.matchKeyFilter?.takeIf(String::isNotBlank)?.let(::setOf).orEmpty() }
        if (matchKeys.isNotEmpty()) {
            where += "match_key IN (${matchKeys.joinToString(",") { "?" }})"
            args += matchKeys.sorted()
        }
        val markets = request.marketFilters
            .ifEmpty { setOf(request.marketFilter) }
            .map(::canonicalMarketFamilyLabel)
            .filterNot { market ->
                market.equals("Any", ignoreCase = true) || market.equals("All", ignoreCase = true)
            }
            .toSet()
        if (markets.isNotEmpty()) {
            where += "market_family IN (${markets.joinToString(",") { "?" }})"
            args += markets.sorted()
        }
        if (strongQualityOnly) {
            where += "strict_sample>=?"
            args += StrictBetRules.QUALITY_SAMPLE.toString()
            where += "strict_hit_rate>=?"
            args += StrictBetRules.MIN_HIT_RATE.toString()
            where += "evidence_score>=?"
            args += BettingEvidenceScorer.PATTERN_MIN_SCORE.toString()
            where += "selection_odd>=?"
            args += request.minSelectionOdd.toString()
        }
        if (hybridStrongFloorOnly) {
            // Historical score/tier/price must not preselect the outcome of a fixture model.
            where += "selection_odd>?"
            args += SinglesOddsPreference.EXCLUSIVE_FLOOR.toString()
        }
        val excludedMarkets = PersistentMarketExclusions.excludedCanonicalLabels()
        if (excludedMarkets.isNotEmpty()) {
            where += "market_family NOT IN (${excludedMarkets.joinToString(",") { "?" }})"
            args += excludedMarkets.sorted()
        }
        val sql = """
            SELECT competition_id, snapshot_version, selection_key, match_key, local_date,
                   continent, country, league_code, market_family, selection_odd,
                   exact_recommendation_key, selection_score, evidence_score, source_order,
                   strict_hit_rate, strict_sample, value_tier, recommendation_eligible,
                   policy_premium_eligible, policy_rejection_reason
            FROM prepared_pattern_candidates
            WHERE ${where.joinToString(" AND ")}
            ORDER BY evidence_score DESC, source_order ASC
        """.trimIndent()
        return snapshotStore.readableDatabase.rawQuery(sql, args.toTypedArray()).use { cursor ->
            buildList {
                while (cursor.moveToNext()) {
                    add(
                        PreparedPatternCandidate(
                            competitionId = cursor.getString(0),
                            snapshotVersion = cursor.getString(1),
                            selectionKey = cursor.getString(2),
                            matchKey = cursor.getString(3),
                            localDate = cursor.getString(4),
                            continent = cursor.getString(5),
                            country = cursor.getString(6),
                            league = cursor.getString(7),
                            marketFamily = cursor.getString(8),
                            odd = cursor.getDouble(9),
                            exactRecommendationKey = cursor.getString(10),
                            selectionScore = cursor.getDouble(11),
                            evidenceScore = cursor.getDouble(12),
                            sourceOrder = cursor.getInt(13),
                            strictHitRate = cursor.getDouble(14),
                            strictSample = cursor.getInt(15),
                            valueTier = if (cursor.isNull(16)) null else cursor.getString(16),
                            recommendationEligible = cursor.getInt(17) == 1,
                            policyPremiumEligible = cursor.getInt(18) == 1,
                            policyRejectionReason = if (cursor.isNull(19)) null else cursor.getString(19)
                        )
                    )
                }
            }
        }
    }

    /**
     * Reprice every persisted outcome of the requested fixtures before historical tier gates.
     * Reads existing App-Ready models only; no model fitting, source generation or provider calls.
     * Candidate metadata supplies diagnostics, not fixture/market eligibility or probability.
     */
    private fun queryProbabilityFirstUat(
        oddsFeed: OddsFeed,
        request: PatternBetsRequest,
        requestLabel: String,
        forcedScopeId: String?,
        generation: PreparedPatternGeneration = requireCurrentGeneration()
    ): PatternBetsToolRunResult {
        val startedAt = System.nanoTime()

        // Deliberately use the legacy/default candidate breadth. In the Hybrid engine the
        // visible Strong tier is rebuilt by HybridUatRanking rather than the persisted Value tier,
        // so do not pre-trim the candidate universe by STRONG_VALUE metadata.
        val persistedCandidates = loadCandidates(
            generationId = generation.generationId,
            request = request,
            strongQualityOnly = false,
            hybridStrongFloorOnly = true
        )
        val selectionsByReference = buildMap<String, PatternBackedSelection> {
            scopePatternOddsFeed(oddsFeed, request).matches
                .groupBy(::bettingCompetitionId).forEach { (competitionId, matches) ->
                    val version = snapshotStore.latestReadySnapshotVersion(competitionId)
                        ?: return@forEach
                    val feed = snapshotStore.loadPreparedMatchFeed(
                        competitionId, version, matches.mapTo(linkedSetOf(), ::preparedMatchKey)
                    ) ?: return@forEach
                    val loaded = snapshotStore.loadForFeed(
                        competitionId, version, feed, PreparedSelectionPurpose.ALL
                    )?.selections.orEmpty()
                    loaded.forEach { selection ->
                        put(preparedPatternSelectionReference(competitionId, preparedSelectionKey(selection)), selection)
                    }
                }
        }
        val resolvedFeed = preparedFeedForSelections(selectionsByReference.values)
        val scopedFeed = scopePatternOddsFeed(resolvedFeed, request)
        val scopedPreparedMatchKeys = scopedFeed.matches
            .mapTo(linkedSetOf(), ::preparedMatchKey)

        val scopedRows = persistedCandidates.filter { candidate ->
            val selection = selectionsByReference[candidate.referenceKey] ?: return@filter false
            preparedMatchKey(selection.match) in scopedPreparedMatchKeys &&
                candidate.allowsScope(request) &&
                requestedBettingMarketAllows(selection, request) &&
                !PersistentMarketExclusions.excludes(selection)
        }

        val eligibleSelections = selectionsByReference.values.filter { selection ->
            preparedMatchKey(selection.match) in scopedPreparedMatchKeys &&
                requestedBettingMarketAllows(selection, request) &&
                !PersistentMarketExclusions.excludes(selection) &&
                SinglesOddsPreference.allows(selection.odd, request.minSelectionOdd) &&
                !RetiredBettingMarketPolicy.isRetiredRawMarket(selection.oddsSelection.market) &&
                ModelSettlementContract.isRecommendationSettleable(selection) &&
                passesBaseBettingValidity(selection) &&
                PreparedBettingDecisionRegistry.lookup(selection)?.identity != null &&
                isSaneExactOdd(selection) &&
                (!request.halfLineOnly || isHalfLineOrNonLine(selection))
        }
        val eligibleKeys = eligibleSelections.mapTo(hashSetOf(), ::preparedSelectionKey)
        val eligibleRows = scopedRows.filter { it.selectionKey in eligibleKeys }

        if (BuildConfig.UAT_BUILD) {
            // Read-only full funnel audit: never re-rank/reject/promote a pick here.
            // Each histogram is grouped by its exact market identity, not by
            // Over/Under direction, so absent 1X2 and DC remain visible in logs.
            fun histogram(rows: List<PreparedPatternCandidate>): String =
                rows.groupingBy { candidate ->
                    selectionsByReference[candidate.referenceKey]
                        ?.let(PreparedBettingDecisionRegistry::lookup)
                        ?.identity?.subMarketKey ?: "UNKNOWN"
                }.eachCount().toSortedMap().entries.joinToString(",") { (market, count) ->
                    "$market:$count"
                }
            val resultShadow = scopedRows.mapNotNull { candidate ->
                val selection = selectionsByReference[candidate.referenceKey]
                    ?: return@mapNotNull null
                val subMarket = PreparedBettingDecisionRegistry.lookup(selection)?.identity?.subMarketKey
                if (subMarket !in setOf("RESULT_1X2", "RESULT_DOUBLE_CHANCE")) {
                    return@mapNotNull null
                }
                val context = PreparedProbabilityFirstContextRegistry.lookup(selection)
                val bookmaker = PreparedBettingEvidenceRegistry.lookup(selection)
                    ?: return@mapNotNull null
                val shadowPass = ResultMarketPolicy.shadowResultValueEligible(
                    odd = selection.odd,
                    modelProbability = context?.modelProbability,
                    marketProbability = bookmaker.marketProbability,
                    historicalSample = candidate.strictSample
                )
                Triple(subMarket ?: "UNKNOWN", candidate.policyPremiumEligible, shadowPass)
            }
            val resultDiagnostics = resultShadow.groupBy { it.first }.toSortedMap()
                .entries.joinToString(";") { (market, candidates) ->
                    "$market:scoped=${candidates.size}" +
                        ",policyV2=${candidates.count { it.second }}" +
                        ",shadowValue=${candidates.count { it.third }}" +
                        ",shadowOnly=${candidates.count { it.third && !it.second }}"
                }
            log(
                "value-first-market-funnel scoped=[${histogram(scopedRows)}] " +
                    "eligible=[${histogram(eligibleRows)}] " +
                    "result-shadow=[$resultDiagnostics]"
            )
        }

        data class HybridSelection(
            val selection: PatternBackedSelection,
            val score: HybridUatRanking.Score
        )

        val candidateByReference = persistedCandidates.associateBy(PreparedPatternCandidate::referenceKey)
        val ranked = eligibleSelections.mapNotNull { selection ->
            val candidate = candidateByReference[preparedPatternSelectionReference(
                bettingCompetitionId(selection.match), preparedSelectionKey(selection))]
            val score = HybridUatRanking.evaluate(
                selection = selection,
                candidate = candidate,
                marketPreferred = false,
                threeWayResult = false
            ) ?: return@mapNotNull null
            HybridSelection(selection, score)
        }

        val safeRows = ranked.filter { it.score.safetyPassed }
        val strongRows = safeRows.filter { HybridUatRanking.qualifiesStrong(it.score) }
        if (BuildConfig.UAT_BUILD) {
            fun scoreHistogram(rows: List<HybridSelection>): String =
                rows.groupingBy { row ->
                    PreparedBettingDecisionRegistry.lookup(row.selection)?.identity
                        ?.subMarketKey ?: "UNKNOWN"
                }.eachCount().toSortedMap().entries.joinToString(",") { (market, count) ->
                    "$market:$count"
                }
            log(
                "value-first-scored-funnel scored=[${scoreHistogram(ranked)}] " +
                    "safe=[${scoreHistogram(safeRows)}] " +
                    "strong=[${scoreHistogram(strongRows)}]"
            )
        }

        // Collapse redundant line variants per exact target, not every market/team in a family.
        val allStrongSelections = strongRows
            .groupBy { row -> HybridUatRanking.opinionKey(row.selection) }
            .mapNotNull { (_, familyRows) ->
                familyRows.maxWithOrNull(
                    compareBy<HybridSelection> { it.score.rankingScore }
                        .thenBy { it.score.expectedValue }
                        .thenBy { it.score.reliability }
                        .thenBy { if (it.selection.odd >= 2.0) 1 else 0 }
                        .thenBy { preparedSelectionKey(it.selection) }
                )
            }
            .sortedWith(
                compareByDescending<HybridSelection> { it.score.rankingScore }
                    .thenByDescending { it.score.expectedValue }
                    .thenByDescending { it.score.reliability }
                    .thenByDescending { if (it.selection.odd >= 2.0) 1 else 0 }
                    .thenBy { preparedSelectionKey(it.selection) }
            )

        val history = confidenceSnapshot()
        val confidenceByKey = allStrongSelections.associate { row ->
            val current = HybridUatRanking.confidenceTier(row.score)
            val historical = if (current == ModelPerformanceConfidenceTier.HIGH_CONFIDENCE) {
                val context = ModelPerformanceConfidenceContext(
                    family = normalizedMarketIdentity(row.selection)?.family,
                    odd = row.selection.odd,
                    predictionSource = row.score.predictionSource,
                    modelProbability = row.score.probability,
                    edge = row.score.edge,
                    competition = row.selection.match.competition,
                    leagueCode = row.selection.match.leagueCode
                )
                if (history.confirmsFixtureHigh(context)) ModelPerformanceConfidenceTier.HIGH_CONFIDENCE
                    else ModelPerformanceConfidenceTier.DEVELOPING
            } else ModelPerformanceConfidenceTier.DEVELOPING
            preparedSelectionKey(row.selection) to HybridUatRanking.combineConfidence(current, historical)
        }

        // High / Confirmed / Developing are filters over the complete Strong universe.
        val requestedConfidence = request.valueTrendFilter.confidenceTier
        // New Singles use >1.80; this boundary never applies to issued historical records.
        val minimumOddRows = allStrongSelections.filter {
            SinglesOddsPreference.allows(it.selection.odd, request.minSelectionOdd)
        }
        val visibleStrongRows = if (requestedConfidence == null) {
            minimumOddRows
        } else {
            minimumOddRows.filter { row ->
                confidenceByKey[preparedSelectionKey(row.selection)] == requestedConfidence
            }
        }

        // Strong returns every independently qualifying family in the requested scope.
        val suggestions = visibleStrongRows.map { row ->
            val selection = row.selection
            PatternBetSuggestion(
                match = selection.match,
                possibleBet = selection,
                selections = listOf(selection),
                estimatedOdds = selection.odd,
                rawProductOdds = selection.odd,
                correlationLevel = "Single",
                averageHitRate = strictEvidence(selection)?.hitRate ?: selection.hitRate
            )
        }

        val visibleSelections = visibleStrongRows.map(HybridSelection::selection)
        val strongSelectionKeys = suggestions
            .mapTo(linkedSetOf()) { suggestion -> preparedSelectionKey(suggestion.possibleBet) }
        val hybridConfidenceBySelectionKey = visibleStrongRows.associate { row ->
            preparedSelectionKey(row.selection) to confidenceByKey.getValue(preparedSelectionKey(row.selection))
        }
        val evidenceBySelectionKey = visibleSelections.mapNotNull { selection ->
            PreparedBettingEvidenceRegistry.lookup(selection)?.let { evidence ->
                PatternTrendCoverageAudit.selectionKey(selection) to SharedBettingEvidence(
                    bookmaker = evidence,
                    trend = null
                )
            }
        }.toMap()

        val result = PatternBetsToolResult(
            selections = visibleSelections,
            paroliSelections = emptyList(),
            suggestions = suggestions,
            paroli = null,
            earlySignals = emptyList(),
            parolis = emptyList()
        )
        val elapsedMs = elapsedMilliseconds(startedAt)
        val rejectedSafety = ranked.count { !it.score.safetyPassed }
        log(
            "hybrid query=${elapsedMs}ms generation=${generation.generationId.take(12)} " +
                "legacyCandidates=${persistedCandidates.size} scoped=${scopedRows.size} " +
                "eligible=${eligibleSelections.size} scored=${ranked.size} safe=${safeRows.size} " +
                "strongSelections=${visibleStrongRows.size} rejectedSafety=${rejectedSafety} " +
                "scope=${forcedScopeId.orEmpty()}"
        )

        return PatternBetsToolRunResult(
            allSelections = eligibleSelections,
            singleSelections = visibleSelections,
            paroliSelections = emptyList(),
            suggestions = suggestions,
            paroli = null,
            earlySignals = emptyList(),
            result = result,
            sourceMs = elapsedMs,
            requestLabel = requestLabel,
            paritySnapshots = emptyList(),
            sharedEvidenceBySelectionKey = evidenceBySelectionKey,
            trendCoverage = PatternTrendCoverageReport(
                totalSelections = eligibleSelections.size,
                mappedSelections = 0,
                evidenceSelections = 0,
                completeLast5Selections = 0,
                rows = emptyList()
            ),
            alternativePoolIndex = BettingAlternativePoolIndex.EMPTY,
            singleAlternativesBySelectionKey = emptyMap(),
            emptyMessage = null,
            paroliDiagnostics = PatternParoliEligibilityDiagnostics(
                evaluatedCandidates = eligibleSelections.size,
                premiumEligibleSelections = 0,
                distinctPremiumMatches = 0,
                requestedLegs = request.paroliLegCount.coerceAtLeast(2),
                generatedParolis = 0,
                minSelectionOdd = request.minSelectionOdd,
                targetOddsPreference = request.paroliTargetOddsPreference,
                rejectedByReason = mapOf(
                    "HYBRID_SAFETY" to rejectedSafety
                ).filterValues { it > 0 }
            ),
            parolis = emptyList(),
            // Existing UI confidence plumbing uses this field. In the active engine it means
            // "Strong rows accepted by the hybrid gate".
            probabilityFirstStrongSelectionKeys = strongSelectionKeys,
            hybridConfidenceBySelectionKey = hybridConfidenceBySelectionKey,
            fixtureScoresBySelectionKey = visibleStrongRows.associate { preparedSelectionKey(it.selection) to it.score }
        )
    }

    private fun filterCachedStrongByConfidence(
        strongRun: PatternBetsToolRunResult,
        requestedConfidence: ModelPerformanceConfidenceTier
    ): PatternBetsToolRunResult {
        val allowedKeys = strongRun.hybridConfidenceBySelectionKey
            .filterValues { tier -> tier == requestedConfidence }
            .keys
        val visibleSingles = strongRun.singleSelections.filter { selection ->
            preparedSelectionKey(selection) in allowedKeys
        }
        val visibleSuggestions = strongRun.suggestions.filter { suggestion ->
            preparedSelectionKey(suggestion.possibleBet) in allowedKeys
        }
        return strongRun.copy(
            singleSelections = visibleSingles,
            suggestions = visibleSuggestions,
            result = strongRun.result.copy(
                selections = visibleSingles,
                suggestions = visibleSuggestions
            ),
            probabilityFirstStrongSelectionKeys =
                strongRun.probabilityFirstStrongSelectionKeys.intersect(allowedKeys),
            hybridConfidenceBySelectionKey =
                strongRun.hybridConfidenceBySelectionKey.filterKeys { key -> key in allowedKeys },
            fixtureScoresBySelectionKey = strongRun.fixtureScoresBySelectionKey.filterKeys { it in allowedKeys }
        )
    }

    private fun loadPreparedSelections(
        candidates: List<PreparedPatternCandidate>,
        purpose: PreparedSelectionPurpose = PreparedSelectionPurpose.PATTERN
    ): Map<String, PatternBackedSelection> {
        return buildMap {
            candidates
                .groupBy { candidate ->
                    candidate.competitionId to candidate.snapshotVersion
                }
                .forEach { (scope, scopedCandidates) ->
                    val competitionId = scope.first
                    val snapshotVersion = scope.second
                    val requestedSelectionKeys = scopedCandidates
                        .mapTo(linkedSetOf(), PreparedPatternCandidate::selectionKey)

                    val loaded = snapshotStore.loadForSelectionKeys(
                        competitionId = competitionId,
                        snapshotVersion = snapshotVersion,
                        selectionKeys = requestedSelectionKeys,
                        purpose = purpose
                    )?.selections.orEmpty()

                    loaded.forEach { selection ->
                        put(
                            preparedPatternSelectionReference(
                                competitionId,
                                preparedSelectionKey(selection)
                            ),
                            selection
                        )
                    }
                }
        }
    }

    private fun preparedFeedForSelections(
        selections: Collection<PatternBackedSelection>
    ): OddsFeed {
        val matches = selections
            .asSequence()
            .map(PatternBackedSelection::match)
            .distinctBy { match ->
                "${bettingCompetitionId(match)}|${preparedMatchKey(match)}"
            }
            .toList()

        val leagues = matches
            .groupBy { match ->
                listOf(
                    bettingCompetitionId(match),
                    match.leagueCode,
                    match.country,
                    match.competition,
                    match.season
                ).joinToString("|")
            }
            .values
            .map { scopedMatches ->
                val first = scopedMatches.first()
                OddsLeague(
                    leagueCode = first.leagueCode,
                    country = first.country,
                    competition = first.competition,
                    season = first.season,
                    providerLeagueSlug = "",
                    matches = scopedMatches
                )
            }

        return OddsFeed(
            source = "prepared-pattern-selection-fk",
            bookmaker = "prepared",
            generatedAt = "",
            country = matches.map(OddsMatch::country).distinct().singleOrNull().orEmpty(),
            competition = "StatMaker",
            season = matches.map(OddsMatch::season)
                .filter(String::isNotBlank)
                .distinct()
                .joinToString(" / "),
            matches = matches,
            leagues = leagues
        )
    }

    private fun preparedParoliSingleQualityReferences(
        rows: List<PreparedPatternCandidate>,
        selectionsByReference: Map<String, PatternBackedSelection>,
        pool: List<PatternBackedSelection>,
        scoreBySelectionKey: Map<String, Double>
    ): Set<String> {
        val strongestExact = rows
            .groupBy { row -> "${row.matchKey}|${row.exactRecommendationKey}" }
            .mapNotNull { (_, group) -> group.maxByOrNull(PreparedPatternCandidate::selectionScore) }
        val mainSingles = strongestExact
            .groupBy(PreparedPatternCandidate::matchKey)
            .mapNotNull { (_, matchRows) ->
                matchRows.maxWithOrNull(
                    compareBy<PreparedPatternCandidate> { it.selectionScore }
                        .thenBy { it.strictHitRate }
                        .thenBy { it.strictSample }
                        .thenBy { it.odd }
                )
            }
            .mapNotNull { selectionsByReference[it.referenceKey] }

        return buildSet {
            mainSingles.forEach { main ->
                add(
                    preparedPatternSelectionReference(
                        bettingCompetitionId(main.match),
                        preparedSelectionKey(main)
                    )
                )
                preparedSingleAlternatives(
                    current = main,
                    pool = pool,
                    scoreBySelectionKey = scoreBySelectionKey
                ).forEach { alternative ->
                    add(
                        preparedPatternSelectionReference(
                            bettingCompetitionId(alternative.match),
                            preparedSelectionKey(alternative)
                        )
                    )
                }
            }
        }
    }

    private fun preparedSingles(
        rows: List<PreparedPatternCandidate>,
        selectionsByReference: Map<String, PatternBackedSelection>,
        request: PatternBetsRequest
    ): List<PatternBetSuggestion> {
        val rowByReference = rows.associateBy(PreparedPatternCandidate::referenceKey)
        val strongestExact = rows
            .groupBy { row -> "${row.matchKey}|${row.exactRecommendationKey}" }
            .mapNotNull { (_, group) -> group.maxByOrNull(PreparedPatternCandidate::selectionScore) }
        val strongestPerMatch = strongestExact
            .groupBy(PreparedPatternCandidate::matchKey)
            .mapNotNull { (_, matchRows) ->
                matchRows.maxWithOrNull(
                    compareBy<PreparedPatternCandidate> { it.selectionScore }
                        .thenBy { it.strictHitRate }
                        .thenBy { it.strictSample }
                        .thenBy { it.odd }
                )
            }
            .mapNotNull { selectionsByReference[it.referenceKey] }
        val balanced = ResultMarketPolicy.balancedSingles(strongestPerMatch) { selection ->
            val reference = preparedPatternSelectionReference(
                bettingCompetitionId(selection.match),
                preparedSelectionKey(selection)
            )
            rowByReference[reference]?.selectionScore ?: 0.0
        }
        return balanced
            .take(patternSingleResultLimit(request, rows.size))
            .map { selection ->
                PatternBetSuggestion(
                    match = selection.match,
                    possibleBet = selection,
                    selections = listOf(selection),
                    estimatedOdds = selection.odd,
                    rawProductOdds = selection.odd,
                    correlationLevel = "Single",
                    averageHitRate = strictEvidence(selection)?.hitRate ?: selection.hitRate
                )
            }
    }

    private fun preparedSingleAlternatives(
        current: PatternBackedSelection,
        pool: List<PatternBackedSelection>,
        scoreBySelectionKey: Map<String, Double>
    ): List<PatternBackedSelection> {
        val currentScore = scoreBySelectionKey[preparedSelectionKey(current)] ?: preparedPatternSelectionScore(current)
        if (currentScore <= 0.0) return emptyList()
        val minimumScore = currentScore * 0.85
        val ranked = pool.asSequence()
            .filter { candidate -> candidate.match.key == current.match.key }
            .filter { candidate -> preparedPatternCycleKey(candidate) != preparedPatternCycleKey(current) }
            .distinctBy(::preparedPatternCycleKey)
            .map { candidate -> candidate to (scoreBySelectionKey[preparedSelectionKey(candidate)] ?: 0.0) }
            .filter { (_, score) -> score >= minimumScore }
            .sortedWith(
                compareByDescending<Pair<PatternBackedSelection, Double>> { it.second }
                    .thenByDescending { strictEvidence(it.first)?.hitRate ?: 0.0 }
                    .thenByDescending { strictEvidence(it.first)?.sample ?: 0 }
                    .thenByDescending { it.first.odd }
                    .thenBy { preparedPatternDisplayKey(it.first) }
            )
            .map(Pair<PatternBackedSelection, Double>::first)
            .toList()
        val currentIdentity = normalizedMarketIdentity(current)
        val selected = mutableListOf<PatternBackedSelection>()
        val selectedKeys = mutableSetOf<String>()
        val familyCounts = mutableMapOf<String, Int>()
        val familyDirections = mutableMapOf<String, String>()
        val broadCounts = mutableMapOf<String, Int>()

        fun add(candidate: PatternBackedSelection, pass: Int) {
            if (selected.size >= 5) return
            val key = preparedPatternCycleKey(candidate)
            if (key in selectedKeys) return
            val identity = normalizedMarketIdentity(candidate)
            if (currentIdentity != null && identity != null &&
                !DomesticMarketProductionRules.coherentAlternativePair(currentIdentity, identity)
            ) return
            val family = listOf(
                marketFamily(candidate),
                identity?.teamSide.orEmpty(),
                identity?.team?.trim()?.lowercase().orEmpty()
            ).joinToString("|")
            val direction = identity?.selectionSide?.name
                ?: candidate.oddsSelection.selection.trim().lowercase()
            val broad = identity?.broadGroup?.name ?: family
            val familyCount = familyCounts[family] ?: 0
            val broadCount = broadCounts[broad] ?: 0
            val broadLimit = identity?.let(DomesticMarketProductionRules::alternativesPerBroadGroup) ?: 2
            if (pass == 0 && broadCount > 0) return
            if (pass <= 1 && familyCount > 0) return
            if (familyCount >= 2 || broadCount >= broadLimit) return
            val existingDirection = familyDirections[family]
            if (familyCount > 0 && existingDirection != null && existingDirection != direction) return
            selected += candidate
            selectedKeys += key
            familyCounts[family] = familyCount + 1
            broadCounts[broad] = broadCount + 1
            familyDirections.putIfAbsent(family, direction)
        }
        repeat(3) { pass -> ranked.forEach { candidate -> add(candidate, pass) } }
        return selected
    }

    private fun preparedPatternCycleKey(selection: PatternBackedSelection): String {
        val identity = normalizedMarketIdentity(selection)
        return listOf(
            selection.match.key,
            identity?.exactKey.orEmpty(),
            selection.oddsSelection.market,
            selection.oddsSelection.selection,
            selection.oddsSelection.line?.toString().orEmpty(),
            selection.oddsSelection.team.orEmpty()
        ).joinToString("|")
    }

    private fun preparedPatternDisplayKey(selection: PatternBackedSelection): String {
        val identity = normalizedMarketIdentity(selection)
        return listOf(
            selection.match.key,
            identity?.exactKey.orEmpty(),
            selection.selection,
            selection.odd.toString()
        ).joinToString("|")
    }

    private fun preparedPatternScopeId(request: PatternBetsRequest): String {
        val selected = request.competitionFilters.filter(String::isNotBlank).toSet()
        return selected.singleOrNull() ?: UNIFIED_SCOPE
    }

    private fun unavailable(reason: String): PreparedPatternRecommendationsUnavailableException =
        PreparedPatternRecommendationsUnavailableException(
            "Prepared recommendations unavailable/stale ($reason). Run the app-ready update."
        )

    private companion object {
        const val PERF_TAG = "StatMakerPreparedPattern"
        const val HYBRID_RESULT_CACHE_TTL_MS = 30L * 60_000L
        const val MAX_HYBRID_RESULT_CACHE_ENTRIES = 64
        const val UNIFIED_SCOPE = "unified"
        const val MAX_PAROLI_GENERATION_POOL = 25
        const val MAX_VISIBLE_PAROLIS = 5
    }
}
